using System;
using DataStructures.Trees;

namespace DataStructures.Common
{
    public static class Comparers
    {
        /// <summary>
        /// Determines if a specific value is a number.
        /// </summary>
        /// <returns><c>true</c> if the value is a number; otherwise, <c>false</c>.</returns>
        /// <param name="value">Value.</param>
        /// <typeparam name="T">The Type of value.</typeparam>
        public static bool IsNumber<T>(this T value)
        {
            if (value is sbyte) return true;
            if (value is byte) return true;
            if (value is short) return true;
            if (value is ushort) return true;
            if (value is int) return true;
            if (value is uint) return true;
            if (value is long) return true;
            if (value is ulong) return true;
            if (value is float) return true;
            if (value is double) return true;
            if (value is decimal) return true;
            return false;
        }

        public static bool IsEqualTo<T>(this T firstValue, T secondValue) where T : IComparable<T>
        {
            return firstValue.Equals(secondValue);
        }

        public static bool IsGreaterThan<T>(this T firstValue, T secondValue) where T : IComparable<T>
        {
            return firstValue.CompareTo(secondValue) > 0;
        }

        public static bool IsLessThan<T>(this T firstValue, T secondValue) where T : IComparable<T>
        {
            return firstValue.CompareTo(secondValue) < 0;
        }

        public static bool IsGreaterThanOrEqualTo<T>(this T firstValue, T secondValue) where T : IComparable<T>
        {
            return (firstValue.IsEqualTo(secondValue) || firstValue.IsGreaterThan(secondValue));
        }

        public static bool IsLessThanOrEqualTo<T>(this T firstValue, T secondValue) where T : IComparable<T>
        {
            return (firstValue.IsEqualTo(secondValue) || firstValue.IsLessThan(secondValue));
        }


        //
        // METHODS FOR BINARY SEARCH TREE
        // COMAPRES THE VALUE OF TWO NODES TOGETHER
        private static bool HandleNullCases<T>(BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            if (first == null || second == null)
                return false;
            return true;
        }

        public static bool IsEqualTo<T>(this BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            return (HandleNullCases(first, second) && first.Value.CompareTo(second.Value) == 0);
        }

        public static bool IsGreaterThan<T>(this BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            return (HandleNullCases(first, second) && first.Value.CompareTo(second.Value) > 0);
        }

        public static bool IsLessThan<T>(this BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            return (HandleNullCases(first, second) && first.Value.CompareTo(second.Value) < 0);
        }

        public static bool IsLessThanOrEqualTo<T>(this BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            return (first.IsEqualTo(second) || first.IsLessThan(second));
        }

        public static bool IsGreaterThanOrEqualTo<T>(this BSTNode<T> first, BSTNode<T> second) where T : IComparable<T>
        {
            return (first.IsEqualTo(second) || first.IsGreaterThan(second));
        }
    }

}

using System;
using System.Collections.Generic;
using DataStructures.Lists;

namespace DataStructures.Common
{
    public static class Helpers
    {
        /// <summary>
        /// Swap two values in an IList<T> collection given their indexes.
        /// </summary>
        public static void Swap<T>(this IList<T> list, int firstIndex, int secondIndex)
        {
            if (list.Count < 2 || firstIndex == secondIndex)   //This check is not required but Partition function may make many calls so its for perf reason
                return;

            var temp = list[firstIndex];
            list[firstIndex] = list[secondIndex];
            list[secondIndex] = temp;
        }

        /// <summary>
        /// Swap two values in an ArrayList<T> collection given their indexes.
        /// </summary>
        public static void Swap<T>(this ArrayList<T> list, int firstIndex, int secondIndex)
        {
            if (list.Count < 2 || firstIndex == secondIndex)   //This check is not required but Partition function may make many calls so its for perf reason
                return;

            var temp = list[firstIndex];
            list[firstIndex] = list[secondIndex];
            list[secondIndex] = temp;
        }

        /// <summary>
        /// Centralize a text.
        /// </summary>
        public static string PadCenter(this string text, int newWidth, char fillerCharacter = ' ')
        {
            if (string.IsNullOrEmpty(text))
                return text;

            int length = text.Length;
            int charactersToPad = newWidth - length;
            if (charactersToPad < 0) throw new ArgumentException("New width must be greater than string length.", "newWidth");
            int padLeft = charactersToPad / 2 + charactersToPad % 2;
            //add a space to the left if the string is an odd number
            int padRight = charactersToPad / 2;

            return new String(fillerCharacter, padLeft) + text + new String(fillerCharacter, padRight);
        }

        /// <summary>
        /// Populates the specified two-dimensional with a default value.
        /// </summary>
        public static void Populate<T>(this T[,] array, int rows, int columns, T defaultValue = default(T))
        {
            for (int i = 0; i < rows; ++i)
            {
                for (int j = 0; j < columns; ++j)
                {
                    array[i, j] = defaultValue;
                }
            }
        }

    }

}

using System;
using System.Linq;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Text;

namespace DataStructures.Common
{
    /// <summary>
    /// Provides a list of the first 10,000 primes.
    /// This class is a singleton, and read the primes from the file @"Data\PrimesList_10K.csv".
    /// </summary>
    public sealed class PrimesList
    {
        //
        // Singleton implementation with an attempted thread-safety using double-check locking
        // internal datastorage singleton container
        private static PrimesList _instance;

        // lock for thread-safety laziness
        private static readonly object Mutex = new object();

        //
        // INSTANCE VARIABLES
        private readonly static List<int> _primes = new List<int>();

        // Picked the HashPrime to be (101) because it is prime, and if the ‘hashSize - 1’ is not a multiple of this HashPrime, which is 
        // enforced in _getUpperBoundPrime, then expand function has the potential of being every value from 1 to hashSize - 1. 
        // The choice is largely arbitrary.
        public const int HASH_PRIME = 101;


        /// <summary>
        /// Empty private constructor.
        /// </summary>
        private PrimesList() { }

        /// <summary>
        /// Returns the singleton instance of this class.
        /// </summary>
        public static PrimesList Instance
        {
            get
            {
                if (_instance == null)
                {
                    lock (Mutex)
                    {
                        if (_instance == null)
                        {
                            _initializeData();
                            _instance = new PrimesList();
                        }
                    }
                }

                return _instance;
            }
        }

        /// <summary>
        /// Initializes the primes document path and list.
        /// </summary>
        private static void _initializeData()
        {
			string[] lines = _readResource("DataStructures.Data.PrimesDocument_10K.csv");

			foreach (var line in lines)
            {
                // Split the line by commas and convert the collection to a list.
                var numbersAsStrings = line.Split(',').ToList<string>();

                // defensive check against empty strings.
                numbersAsStrings.RemoveAll(item => string.IsNullOrEmpty(item) == true);

                if (numbersAsStrings.Count > 0)
                {
                    try
                    {
                        // cast them into integers and add them to the primes list
                        var numbers = numbersAsStrings.Select(item => Convert.ToInt32(item)).ToList<int>();
                        _primes.AddRange(numbers);
                    }
                    catch (Exception e)
                    {
                        throw new Exception(line.Replace("\r","{\\r}").Replace("\n", "{\\n}"), e);
                    }
                }
            }
        }

        /// <summary>
        /// Return count of primes.
        /// </summary>
        public int Count
        {
            get { return _primes.Count; }
        }

        /// <summary>
        /// Returns prime number at the specified index.
        /// </summary>
        public int this[int index]
        {
            get
            {
                if (index < 0 || index >= _primes.Count)
                    throw new ArgumentOutOfRangeException();

                return _primes[index];
            }
        }

        /// <summary>
        /// Checks if a number is a Prime Number.
        /// </summary>
        public bool IsPrime(int candidate)
        {
            if ((candidate & 1) != 0)
            {
                int limit = (int)Math.Sqrt(candidate);

                for (int divisor = 3; divisor <= limit; divisor += 2)
                {
                    if ((candidate % divisor) == 0)
                        return false;
                }

                return true;
            }

            return (candidate == 2);
        }

        /// <summary>
        /// Returns the next biggest prime number.
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        public int GetNextPrime(int number)
        {
            if (number < 0)
                throw new ArgumentException("Number should be greater than or equal to 0.");

            for (int i = 0; i < _primes.Count; i++)
            {
                if (_primes[i] >= number)
                    return _primes[i];
            }

            // Outside of our predefined table. Compute the prime the hard way. 
            for (int i = (number | 1); i < Int32.MaxValue; i += 2)
            {
                if (IsPrime(i) && ((i - 1) % HASH_PRIME != 0))
                    return i;
            }

            return number;
        }

        /// <summary>
        /// Returns the next minimum prime number.
        /// </summary>
        public int GetPreviousPrime(int number)
        {
            if (number < 0)
                throw new ArgumentException("Number should be greater than or equal to 0.");

            for (int i = 0; i < _primes.Count; i++)
            {
                if (_primes[i] >= number)
                    return _primes[i];
            }

            // Outside of our predefined table. Compute the prime the hard way. 
            for (int i = (number | 1); i < Int32.MaxValue; i += 2)
            {
                if (IsPrime(i) && ((i - 1) % HASH_PRIME != 0))
                    return i;
            }

            return number;
        }

        /// <summary>
        /// Returns the read-only IList of primes
        /// </summary>
        public IList<int> GetAll
        {
            get { return _primes.AsReadOnly(); }
        }

        /// <summary>
        /// Copy the primes list to an array, starting from a specified index.
        /// </summary>
        public void CopyTo(int[] array, int index = 0)
        {
            if (array == null)
                array = new int[_primes.Count];

            if (array.Length <= index)
                throw new ArgumentOutOfRangeException();

            int count = array.Length - index;
            int arrayIndex = index;

            if (count - _primes.Count > 0)
                count = _primes.Count;

            for (int i = 0; i < count; i++)
            {
                array[arrayIndex] = _primes[i];
                arrayIndex++;
            }
        }

        /// <summary>
        /// Reads an embedded resource as a text file.
        /// </summary>
        /// <returns></returns>
        private static string[] _readResource(string resourceName)
        {
	        try
	        {
		        using (var stream = typeof(PrimesList).GetTypeInfo().Assembly.GetManifestResourceStream(resourceName))
		        using (var reader = new StreamReader(stream ?? throw new InvalidOperationException("Failed to read resource"), Encoding.UTF8))
			        return reader.ReadToEnd().Split("\n");
	        }
	        catch (Exception ex)
	        {
		        throw new Exception($"Failed to read resource {resourceName}", ex);
	        }
        }
    }
}

/***
 * Chained Hash Table.
 * 
 * A hash table that implements the Separate-Chaining scheme for resolving keys-collisions. It also implements auto-resizing (expansion and contraction).
 */

using System;
using System.Collections.Generic;

using DataStructures.Common;
using DataStructures.Lists;

namespace DataStructures.Dictionaries
{
    /// <summary>
    /// Hash Table with Chaining.
    /// </summary>
    public class ChainedHashTable<TKey, TValue> : IDictionary<TKey, TValue> where TKey : IComparable<TKey>
    {
        /// <summary>
        /// Used in the ensure capacity function
        /// </summary>
        public enum CapacityManagementMode
        {
            Contract = 0,
            Expand = 1
        }

        /// <summary>
        /// INSTANCE VARIABLES.
        /// </summary>
        private int _size;
        private int _freeSlotsCount;
        private decimal _slotsLoadFactor;
        private const int _defaultCapacity = 8;
        private DLinkedList<TKey, TValue>[] _hashTableStore;
        private List<TKey> _keysCollection { get; set; }
        private List<TValue> _valuesCollection { get; set; }

        // Keys and Values Comparers
        private EqualityComparer<TKey> _keysComparer { get; set; }
        private EqualityComparer<TValue> _valuesComparer { get; set; }

        // The C# Maximum Array Length (before encountering overflow)
        // Reference: http://referencesource.microsoft.com/#mscorlib/system/array.cs,2d2b551eabe74985
        private const int MAX_ARRAY_LENGTH = 0X7FEFFFFF;

        // Initial hash value.
        private const uint INITIAL_HASH = 0x9e3779b9;


        /// <summary>
        /// CONSTRUCTOR
        /// </summary>
        public ChainedHashTable()
        {
            this._size = 0;
            this._hashTableStore = new DLinkedList<TKey, TValue>[_defaultCapacity];
            this._freeSlotsCount = this._hashTableStore.Length;
            this._keysComparer = EqualityComparer<TKey>.Default;
            this._valuesComparer = EqualityComparer<TValue>.Default;

            this._keysCollection = new List<TKey>();
            this._valuesCollection = new List<TValue>();
        }


        /// <summary>
        /// Rehash the the current collection elements to a new collection.
        /// </summary>
        private void _rehash(ref DLinkedList<TKey, TValue>[] newHashTableStore, int oldHashTableSize)
        {
            // Reset the free slots count
            this._freeSlotsCount = newHashTableStore.Length;

            for (int i = 0; i < oldHashTableSize; ++i)
            {
                var chain = _hashTableStore[i];

                if (chain != null && chain.Count > 0)
                {
                    var head = chain.Head;

                    while (head != null)
                    {
                        uint hash = _getHashOfKey(head.Key, newHashTableStore.Length);

                        if (newHashTableStore[hash] == null)
                        {
                            _freeSlotsCount--;
                            newHashTableStore[hash] = new DLinkedList<TKey, TValue>();
                        }

                        newHashTableStore[hash].Append(head.Key, head.Value);

                        head = head.Next;
                    }
                }
            }//end-for
        }

        /// <summary>
        /// Contracts the capacity of the keys and values arrays.
        /// </summary>
        private void _contractCapacity()
        {
            int oneThird = (_hashTableStore.Length / 3);
            int twoThirds = 2 * oneThird;

            if (_size <= oneThird)
            {
                int newCapacity = (_hashTableStore.Length == 0 ? _defaultCapacity : twoThirds);

                // Try to expand the size
                DLinkedList<TKey, TValue>[] newHashTableStore = new DLinkedList<TKey, TValue>[newCapacity];

                // Rehash
                if (_size > 0)
                {
                    _rehash(ref newHashTableStore, _hashTableStore.Length);
                }//end-if

                _hashTableStore = newHashTableStore;
            }
        }

        /// <summary>
        /// Expands the capacity of the keys and values arrays.
        /// </summary>
        private void _expandCapacity(int minCapacity)
        {
            if (_hashTableStore.Length < minCapacity)
            {
                int newCapacity = (_hashTableStore.Length == 0 ? _defaultCapacity : _hashTableStore.Length * 2);

                // Make sure it doesn't divide by 2 or 10
                if (newCapacity % 2 == 0 || newCapacity % 10 == 0)
                    newCapacity = newCapacity + 1;

                // Handle overflow
                if (newCapacity >= MAX_ARRAY_LENGTH)
                    newCapacity = MAX_ARRAY_LENGTH;
                else if (newCapacity < minCapacity)
                    newCapacity = minCapacity;

                // Try to expand the size
                try
                {
                    DLinkedList<TKey, TValue>[] newHashTableStore = new DLinkedList<TKey, TValue>[newCapacity];

                    // Rehash
                    if (_size > 0)
                    {
                        _rehash(ref newHashTableStore, _hashTableStore.Length);
                    }//end-if

                    _hashTableStore = newHashTableStore;
                }
                catch (OutOfMemoryException)
                {
                    throw;
                }
            }
        }

        /// <summary>
        /// A high-level functon that handles both contraction and expansion of the internal collection.
        /// </summary>
        /// <param name="mode">Contract or Expand.</param>
        /// <param name="newSize">The new expansion size.</param>
        private void _ensureCapacity(CapacityManagementMode mode, int newSize = -1)
        {
            // If the size of the internal collection is less than or equal to third of 
            // ... the total capacity then contract the internal collection
            int oneThird = (_hashTableStore.Length / 3);

            if (mode == CapacityManagementMode.Contract && _size <= oneThird)
            {
                _contractCapacity();
            }
            else if (mode == CapacityManagementMode.Expand && newSize > 0)
            {
                _expandCapacity(newSize);
            }
        }

        /// <summary>
        /// Hash Function.
        /// The universal hashing principle method.
        /// </summary>
        private uint _universalHashFunction(TKey key, int length)
        {
            if (length < 0)
                throw new IndexOutOfRangeException();

            // Hashes
            uint prehash = 0, hash = INITIAL_HASH;

            // Primes
            int a = 197, b = 4049, p = 7199369;

            prehash = _getPreHashOfKey(key);
            hash = Convert.ToUInt32(((a * prehash + b) % p) % length);

            return hash;
        }

        /// <summary>
        /// Hash Function.
        /// The division method hashing.
        /// </summary>
        private uint _divisionMethodHashFunction(TKey key, int length)
        {
            uint prehash = 0, hash = INITIAL_HASH;

            if (length < 0)
                throw new IndexOutOfRangeException();

            if (key is string && key.IsEqualTo(default(TKey)) == false)
            {
                var stringKey = Convert.ToString(key);

                for (int i = 0; i < stringKey.Length; ++i)
                {
                    hash = (hash ^ stringKey[i]) + ((hash << 26) + (hash >> 6));
                }

                if (hash > length)
                    hash = Convert.ToUInt32(hash % length);
            }
            else
            {
                prehash = _getPreHashOfKey(key);
                hash = Convert.ToUInt32((37 * prehash) % length);
            }

            return hash;
        }

        /// <summary>
        /// Returns an integer that represents the key.
        /// Used in the _hashKey function.
        /// </summary>
        private uint _getPreHashOfKey(TKey key)
        {
            return Convert.ToUInt32(Math.Abs(_keysComparer.GetHashCode(key)));
        }

        /// <summary>
        /// Returns a key from 0 to m where m is the size of the keys-and-values map. The hash serves as an index.
        /// </summary>
        private uint _getHashOfKey(TKey key, int length)
        {
            return _universalHashFunction(key, length);
        }

        /// <summary>
        /// Returns a key from 0 to m where m is the size of the keys-and-values map. The hash serves as an index.
        /// Division Method.
        /// </summary>
        private uint _getHashOfKey(TKey key)
        {
            return _universalHashFunction(key, _hashTableStore.Length);
        }

        /// <summary>
        /// Return count of elements in the hash table.
        /// </summary>
        public int Count
        {
            get { return _size; }
        }

        /// <summary>
        /// Checks if the hash table is readonly.
        /// </summary>
        public bool IsReadOnly
        {
            get { return false; }
        }

        /// <summary>
        /// Checks if the hash table is empty.
        /// </summary>
        public bool IsEmpty
        {
            get { return Count == 0; }
        }

        /// <summary>
        /// Checks whether key exists in the hash table.
        /// </summary>
        public bool ContainsKey(TKey key)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
            {
                return _hashTableStore[hashcode].ContainsKey(key);
            }

            // else
            return false;
        }

        /// <summary>
        /// Checks whether a key-value pair exist in the hash table.
        /// </summary>
        public bool Contains(KeyValuePair<TKey, TValue> item)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(item.Key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
            {
                try
                {
                    var existingPair = _hashTableStore[hashcode].Find(item.Key);

                    if (existingPair.Key.IsEqualTo(item.Key) && _valuesComparer.Equals(existingPair.Value, item.Value))
                        return true;
                }
                catch (KeyNotFoundException)
                {
                    // do nothing
                }
            }

            // else
            return false;
        }

        /// <summary>
        /// List of hash table keys.
        /// </summary>
        public ICollection<TKey> Keys
        {
            get { return _keysCollection; }
        }

        /// <summary>
        /// List of hash table values.
        /// </summary>
        public ICollection<TValue> Values
        {
            get { return _valuesCollection; }
        }


        /// <summary>
        /// Tries to get the value of key which might not be in the dictionary.
        /// </summary>
        public bool TryGetValue(TKey key, out TValue value)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
            {
                try
                {
                    var existingPair = _hashTableStore[hashcode].Find(key);
                    value = existingPair.Value;
                    return true;
                }
                catch (KeyNotFoundException)
                {
                    // do nothing
                }
            }

            // NOT FOUND
            value = default(TValue);
            return false;
        }

        /// <summary>
        /// Gets or sets the value of a key.
        /// </summary>
        public TValue this[TKey key]
        {
            get
            {
                // Get hash of the key
                var hashcode = _getHashOfKey(key);

                // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
                if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
                {
                    try
                    {
                        var existingPair = _hashTableStore[hashcode].Find(key);
                        return existingPair.Value;
                    }
                    catch (KeyNotFoundException)
                    {
                        // do nothing
                    }
                }

                // NOT FOUND
                throw new KeyNotFoundException();
            }
            set
            {
                // Get hash of the key
                var hashcode = _getHashOfKey(key);

                // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
                if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
                {
                    bool exists = _hashTableStore[hashcode].ContainsKey(key);

                    if (exists == true)
                        _hashTableStore[hashcode].UpdateValueByKey(key, value);
                }

                // NOT FOUND
                throw new KeyNotFoundException();
            }
        }

        /// <summary>
        /// Add a key and value to the hash table.
        /// </summary>
        public void Add(TKey key, TValue value)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] == null)
            {
                // This is an empty slot. Initialize the chain of collisions.
                _hashTableStore[hashcode] = new DLinkedList<TKey, TValue>();

                // Decrease the number of free slots.
                _freeSlotsCount--;
            }
            else if (_hashTableStore[hashcode].Count > 0)
            {
                if (_hashTableStore[hashcode].ContainsKey(key) == true)
                    throw new ArgumentException("Key already exists in the hash table.");
            }

            _hashTableStore[hashcode].Append(key, value);
            _size++;

            //Add the key-value to the keys and values collections
            _keysCollection.Add(key);
            _valuesCollection.Add(value);

            _slotsLoadFactor = Decimal.Divide(
                Convert.ToDecimal(_size),
                Convert.ToDecimal(_hashTableStore.Length));

            // Capacity management
            if (_slotsLoadFactor.IsGreaterThanOrEqualTo(Convert.ToDecimal(0.90)))
            {
                _ensureCapacity(CapacityManagementMode.Expand, _hashTableStore.Length + 1);
            }
        }

        /// <summary>
        /// Add a key-value pair to the hash table.
        /// </summary>
        public void Add(KeyValuePair<TKey, TValue> item)
        {
            Add(item.Key, item.Value);
        }

        /// <summary>
        /// Remove a key from the hash table and return the status.
        /// </summary>
        public bool Remove(TKey key)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
            {
                try
                {
                    var keyValuePair = _hashTableStore[hashcode].Find(key);

                    if (keyValuePair.Key.IsEqualTo(key))
                    {
                        _hashTableStore[hashcode].RemoveBy(key);
                        _size--;

                        // check if no other keys exist in this slot.
                        if (_hashTableStore[hashcode].Count == 0)
                        {
                            // Nullify the chain of collisions at this slot.
                            _hashTableStore[hashcode] = null;

                            // Increase the number of free slots.
                            _freeSlotsCount++;

                            // Capacity management
                            _ensureCapacity(CapacityManagementMode.Contract);
                        }

                        _keysCollection.Remove(key);
                        _valuesCollection.Remove(keyValuePair.Value);

                        return true;
                    }
                }
                catch
                {
                    // do nothing
                }
            }

            // else
            return false;
        }

        /// <summary>
        /// Remove a key-value pair from the hash table and return the status.
        /// </summary>
        public bool Remove(KeyValuePair<TKey, TValue> item)
        {
            // Get hash of the key
            var hashcode = _getHashOfKey(item.Key);

            // The chain of colliding keys are found at _keysValuesMap[hashcode] as a doubly-linked-list.
            if (_hashTableStore[hashcode] != null && _hashTableStore[hashcode].Count > 0)
            {
                try
                {
                    var keyValuePair = _hashTableStore[hashcode].Find(item.Key);

                    if (keyValuePair.Key.IsEqualTo(item.Key) && _valuesComparer.Equals(keyValuePair.Value, item.Value))
                    {
                        _hashTableStore[hashcode].RemoveBy(item.Key);
                        _size--;

                        // check if no other keys exist in this slot.
                        if (_hashTableStore[hashcode].Count == 0)
                        {
                            // Nullify the chain of collisions at this slot.
                            _hashTableStore[hashcode] = null;

                            // Increase the number of free slots.
                            _freeSlotsCount++;

                            // Capacity management
                            _ensureCapacity(CapacityManagementMode.Contract);
                        }

                        _keysCollection.Remove(keyValuePair.Key);
                        _valuesCollection.Remove(keyValuePair.Value);

                        return true;
                    }
                }
                catch
                {
                    // do nothing
                }
            }

            // else
            return false;
        }

        /// <summary>
        /// Copy the key-value pairs in the hash table to an array starting from the specified index.
        /// </summary>
        public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
        {
            if (array == null)
                array = new KeyValuePair<TKey, TValue>[_size];

            int i = arrayIndex;
            int hashTableIndex = 0;
            var currentChainNode = new DLinkedListNode<TKey, TValue>();

            while (hashTableIndex < _hashTableStore.Length && i < array.Length)
            {
                if (_hashTableStore[hashTableIndex] != null)
                {
                    currentChainNode = _hashTableStore[hashTableIndex].Head;
                    while (currentChainNode != null && i < array.Length)
                    {
                        var pair = new KeyValuePair<TKey, TValue>(currentChainNode.Key, currentChainNode.Value);
                        array[i] = pair;
                        i++;
                        currentChainNode = currentChainNode.Next;
                    }
                }

                hashTableIndex++;
            }
        }

        /// <summary>
        /// Clears this instance.
        /// </summary>
        public void Clear()
        {
            // Clear the elements in the store
            Array.Clear(_hashTableStore, 0, _hashTableStore.Length);

            // Re-initialize to empty collection.
            _hashTableStore = new DLinkedList<TKey, TValue>[_defaultCapacity];

            _size = 0;
            _slotsLoadFactor = 0;
            _freeSlotsCount = _hashTableStore.Length;
        }


        public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator()
        {
            for (int i = 0; i < _hashTableStore.Length; i++)
            {
                var chain = _hashTableStore[i];
                if (chain != null && chain.Count > 0)
                {
                    var node = chain.Head;
                    while (node != null)
                    {
                        yield return new KeyValuePair<TKey, TValue>(node.Key, node.Value);
                        node = node.Next;
                    }
                }
            }
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

    }

}

/***
 * Cuckoo Hash Table.
 * 
 * A hash table that implements the Cuckoo Hashing algorithm for resolving keys-collisions. 
 * This is a single-table implementation, the source behind this idea is the work of Mark Allen Weiss, 2014.
 */

using System;
using System.Collections.Generic;

using DataStructures.Common;
using DataStructures.Hashing;
using System.Threading.Tasks;

namespace DataStructures.Dictionaries
{
    /// <summary>
    /// THE CUCKOO HASH TABLE Data Structure.
    /// </summary>
    public class CuckooHashTable<TKey, TValue> where TKey : IComparable<TKey>
    {
        /// <summary>
        /// THE CUCKOO HASH TABLE ENTRY
        /// </summary>
        private class CHashEntry
        {
            public TKey Key { get; set; }
            public TValue Value { get; set; }
            public bool IsActive { get; set; }

            public CHashEntry() : this(default(TKey), default(TValue), false) { }

            public CHashEntry(TKey key, TValue value, bool isActive)
            {
                Key = key;
                Value = value;
                IsActive = isActive;
            }
        }


        /// <summary>
        /// INSTANCE VARIABLES
        /// </summary>
        private const int DEFAULT_CAPACITY = 11;
        private const double MAX_LOAD_FACTOR = 0.45;
        private const int ALLOWED_REHASHES = 5;
        private const int NUMBER_OF_HASH_FUNCTIONS = 7; // number of hash functions to use, selected 7 because it's prime. The choice was arbitrary.
        internal readonly PrimesList PRIMES = PrimesList.Instance;

        // Random number generator
        private Random _randomizer;

        private int _size { get; set; }
        private int _numberOfRehashes { get; set; }
        private CHashEntry[] _collection { get; set; }
        private UniversalHashingFamily _universalHashingFamily { get; set; }
        private EqualityComparer<TKey> _equalityComparer = EqualityComparer<TKey>.Default;

        // The C# Maximum Array Length (before encountering overflow)
        // Reference: http://referencesource.microsoft.com/#mscorlib/system/array.cs,2d2b551eabe74985
        private const int MAX_ARRAY_LENGTH = 0X7FEFFFFF;


        /// <summary>
        /// CONSTRUCTOR
        /// </summary>
        public CuckooHashTable()
        {
            _size = 0;
            _numberOfRehashes = 0;
            _randomizer = new Random();
            _collection = new CHashEntry[DEFAULT_CAPACITY];
            _universalHashingFamily = new UniversalHashingFamily(NUMBER_OF_HASH_FUNCTIONS);
        }

        /// <summary>
        /// Expands the size of internal collection.
        /// </summary>
        private void _expandCapacity(int minCapacity)
        {
            int newCapacity = (_collection.Length == 0 ? DEFAULT_CAPACITY : _collection.Length * 2);

            // Handle overflow
            if (newCapacity >= MAX_ARRAY_LENGTH)
                newCapacity = MAX_ARRAY_LENGTH;
            else if (newCapacity < minCapacity)
                newCapacity = minCapacity;

            _rehash(Convert.ToInt32(newCapacity));
        }

        /// <summary>
        /// Contracts the size of internal collection to half.
        /// </summary>
        private void _contractCapacity()
        {
            _rehash(_size / 2);
        }

        /// <summary>
        /// Rehashes the internal internal collection.
        /// Table size stays the same, but generates new hash functions.
        /// </summary>
        private void _rehash()
        {
            _universalHashingFamily.GenerateNewFunctions();
            _rehash(_collection.Length);
        }

        /// <summary>
        /// Rehashes the internal collection to a new size.
        /// New hash table size, but the hash functions stay the same.
        /// </summary>
        private void _rehash(int newCapacity)
        {
            int primeCapacity = PRIMES.GetNextPrime(newCapacity);

            var oldSize = _size;
            var oldCollection = this._collection;

            try
            {
                this._collection = new CHashEntry[newCapacity];

                // Reset size
                _size = 0;

                for (int i = 0; i < oldCollection.Length; ++i)
                {
                    if (oldCollection[i] != null && oldCollection[i].IsActive == true)
                    {
                        _insertHelper(oldCollection[i].Key, oldCollection[i].Value);
                    }
                }
            }
            catch (OutOfMemoryException ex)
            {
                // In case a memory overflow happens, return the data to it's old state
                // ... then throw the exception.
                _collection = oldCollection;
                _size = oldSize;

                throw ex.InnerException;
            }
        }

        /// <summary>
        /// Hashes a key, using the specified hash function number which belongs to the internal hash functions family.
        /// </summary>
        private int _cuckooHash(TKey key, int whichHashFunction)
        {
            if (whichHashFunction <= 0 || whichHashFunction > _universalHashingFamily.NumberOfFunctions)
                throw new ArgumentOutOfRangeException("Which Hash Function parameter must be betwwen 1 and " + NUMBER_OF_HASH_FUNCTIONS + ".");

            int hashCode = Math.Abs(_universalHashingFamily.UniversalHash(_equalityComparer.GetHashCode(key), whichHashFunction));

            return hashCode % _collection.Length;
        }

        /// <summary>
        /// Checks whether there is an entry at the specified position and that the entry is active.
        /// </summary>
        private bool _isActive(int index)
        {
            if (index < 0 || index > _collection.Length)
                throw new IndexOutOfRangeException();

            return (_collection[index] != null && _collection[index].IsActive == true);
        }

        /// <summary>
        /// Returns the array position (index) of the specified key.
        /// </summary>
        private int _findPosition(TKey key)
        {
            // The hash functions numbers are indexed from 1 not zero
            for (int i = 1; i <= NUMBER_OF_HASH_FUNCTIONS; ++i)
            {
                int index = _cuckooHash(key, i);

                if (_isActive(index) && _collection[index].Key.IsEqualTo(key))
                    return index;
            }

            return -1;
        }

        /// <summary>
        /// Inserts a key-value pair into hash table.
        /// </summary>
        private void _insertHelper(TKey key, TValue value)
        {
            int COUNT_LIMIT = 100;
            var newEntry = new CHashEntry(key, value, isActive: true);

            while (true)
            {
                int position, lastPosition = -1;

                for (int count = 0; count < COUNT_LIMIT; count++)
                {
                    // The hash functions numbers are indexed from 1 not zero
                    for (int i = 1; i <= NUMBER_OF_HASH_FUNCTIONS; i++)
                    {
                        position = _cuckooHash(key, i);

                        if (!_isActive(position))
                        {
                            _collection[position] = newEntry;

                            // Increment size
                            ++_size;

                            return;
                        }
                    }

                    // Eviction strategy:
                    // No available spot was found. Choose a random one.
                    int j = 0;
                    do
                    {
                        position = _cuckooHash(key, _randomizer.Next(1, NUMBER_OF_HASH_FUNCTIONS));
                    } while (position == lastPosition && j++ < NUMBER_OF_HASH_FUNCTIONS);

                    // SWAP ENTRY
                    lastPosition = position;

                    var temp = _collection[position];
                    _collection[position] = newEntry;
                    newEntry = temp;

                }//end-for

                if (++_numberOfRehashes > ALLOWED_REHASHES)
                {
                    // Expand the table.
                    _expandCapacity(_collection.Length + 1);

                    // Reset number of rehashes.
                    _numberOfRehashes = 0;
                }
                else
                {
                    // Rehash the table with the same current size.
                    _rehash();
                }
            }//end-while
        }


        /// <summary>
        /// Returns number of items in hash table.
        /// </summary>
        /// <returns></returns>
        public int Count()
        {
            return _size;
        }

        /// <summary>
        /// Returns true if hash table is empty; otherwise, false.
        /// </summary>
        public bool IsEmpty()
        {
            return (_size == 0);
        }

        /// <summary>
        /// Returns the value of the specified key, if exists; otherwise, raises an exception.
        /// </summary>
        public TValue this[TKey key]
        {
            get
            {
                int position = _findPosition(key);

                if (position != -1)
                    return _collection[position].Value;

                throw new KeyNotFoundException();
            }
            set
            {
                if (ContainsKey(key) == true)
                    Update(key, value);

                throw new KeyNotFoundException();
            }
        }

        /// <summary>
        /// Checks if a key exists in the hash table.
        /// </summary>
        /// <param name="key"></param>
        /// <returns></returns>
        public bool ContainsKey(TKey key)
        {
            return (_findPosition(key) != -1);
        }

        /// <summary>
        /// Insert key-value pair into hash table.
        /// </summary>
        public void Add(TKey key, TValue value)
        {
            if (ContainsKey(key))
                throw new Exception("Key already exists in the hash table.");

            if (_size >= _collection.Length * MAX_LOAD_FACTOR)
                _expandCapacity(_collection.Length + 1);

            _insertHelper(key, value);
        }

        /// <summary>
        /// Updates a key-value pair with a new value.
        /// </summary>
        public void Update(TKey key, TValue value)
        {
            int position = _findPosition(key);

            if (position == -1)
                throw new KeyNotFoundException();

            _collection[position].Value = value;
        }

        /// <summary>
        /// Remove the key-value pair specified by the given key.
        /// </summary>
        public bool Remove(TKey key)
        {
            int currentPosition = _findPosition(key);

            if (!_isActive(currentPosition))
                return false;

            // Mark the entry as not active
            _collection[currentPosition].IsActive = false;

            // Decrease the size
            --_size;

            return true;
        }

        /// <summary>
        /// Clears this hash table.
        /// </summary>
        public void Clear()
        {
            this._size = 0;

            Parallel.ForEach(_collection,
                (item) =>
                {
                    if (item != null && item.IsActive == true)
                    {
                        item.IsActive = false;
                    }
                });
        }
    }

}

using System;
using System.Collections.Generic;
using System.Text;

namespace DataStructures.Dictionaries
{
    /// <summary>
    /// Open Addressing Data Structure
    /// </summary>
    /// <typeparam name="TKey"></typeparam>
    /// <typeparam name="TValue"></typeparam>
    public class OpenAddressingHashTable<TKey, TValue> : IDictionary<TKey, TValue> where TKey : IComparable<TKey>
    {

        /// <summary>
        /// Open Addressing Entry
        /// </summary>
        private class OAHashEntry
        {
            public TKey key { get; set; }
            public TValue value { get; set; }
            public bool occupied { get; set; }
            public OAHashEntry(TKey Key, TValue Value, bool occp)
            {
                key = Key;
                value = Value;
                occupied = occp;
            }
        }

        private int _size { get; set; }
        private double _loadFactor { get; set; }
        private int _inTable { get; set; }
        private OAHashEntry[] _table { get; set; }
        private List<TKey> _keys { get; set; }
        private List<TValue> _values { get; set; }

        /// <summary>
        /// CONSTRUCTOR
        /// </summary>
        /// 
        public OpenAddressingHashTable(int size)
        {
            _size = size;
            _loadFactor = 0.40;
            _inTable = 0;
            _table = new OAHashEntry[_size];
            _keys = new List<TKey>();
            _values = new List<TValue>();

            //initialize all values to -1
            for (int i = 0; i < _table.Length; i++)
            {
                //initialize each slot
                _table[i] = new OAHashEntry(default(TKey), default(TValue), false);
            }
        }

        //doubles the size of the table
        private void _expand()
        {
            //will hold contents of _table to copy over
            OAHashEntry[] temp = new OAHashEntry[_size];
            temp = _table;
            //double the size and rehash
            _size *= 2;
            OAHashEntry[] exp = new OAHashEntry[_size];
            for (int i = 0; i < exp.Length; i++)
            {
                //initialize each slot
                exp[i] = new OAHashEntry(default(TKey), default(TValue), false);
            }

            _inTable = 0;
            _table = exp;
            //rehash over the newly sized table
            for (int i = 0; i < temp.Length; i++)
            {
                //this should rehash since the size is now doubled so the hashing will be different
                //inserts the key into _table
                Add(temp[i].key, temp[i].value);
            }
        }

        //rehashes table
        private void _rehash()
        {
            //will hold contents of _table to copy over
            OAHashEntry[] temp = new OAHashEntry[_size];
            temp = _table;

            OAHashEntry[] rehash = new OAHashEntry[_size];
            for (int i = 0; i < rehash.Length; i++)
            {
                //initialize each slot
                rehash[i] = new OAHashEntry(default(TKey), default(TValue), false);
            }

            _inTable = 0;
            _table = rehash;
            //rehash over the newly sized table
            for (int i = 0; i < temp.Length; i++)
            {
                //this should rehash since the size is now doubled so the hashing will be different
                //inserts the key into _table
                Add(temp[i].key, temp[i].value);
            }

        }

        private int _double_hash(TKey key, int i)
        {
            int hash_value = 0;
            int second_hash_value = 0;
            int slot = 0;

            //grabs hash value for a string
            if (typeof(TKey) == typeof(string))
            {
                //https://stackoverflow.com/questions/4092393/value-of-type-t-cannot-be-converted-to
                TKey newTkeyString = (TKey)(object)key;
                string newTkeyString2 = (string)(object)newTkeyString;

                //https://stackoverflow.com/questions/400733/how-to-get-ascii-value-of-string-in-c-sharp
                byte[] asciiBytes = Encoding.ASCII.GetBytes(newTkeyString2);

                int string_value = 0;
                foreach (byte bite in asciiBytes)
                {
                    string_value += (int)bite;
                }

                //calculates first hash values
                hash_value = Convert.ToInt32(string_value) % _size;
                //calculate second hash value
                second_hash_value = 1 + (Convert.ToInt32(string_value) % (_size - 1));
            }
            //grabs a hash value for a char
            else if (typeof(TKey) == typeof(char))
            {
                //https://stackoverflow.com/questions/4092393/value-of-type-t-cannot-be-converted-to
                TKey newTkeyChar = (TKey)(object)key;
                char newTkeyChar2 = (char)(object)newTkeyChar;

                int char_value = (int)newTkeyChar2;

                //calculates first hash values
                hash_value = Convert.ToInt32(char_value) % _size;
                //calculate second hash value
                second_hash_value = 1 + (Convert.ToInt32(char_value) % (_size - 1));
            }
            else
            {
                //calculates first hash values
                hash_value = Convert.ToInt32(key) % _size;
                //calculate second hash value
                second_hash_value = 1 + (Convert.ToInt32(key) % (_size - 1));
            }

            //slot index based on first hash value, second hash value as an offset based on a counter, will also guarentee that the slot will be within the range 0 to size
            slot = (hash_value + (i * second_hash_value)) % _size;

            return slot;
        }

        public void Add(TKey key, TValue value)
        {
            int i = 0;

            //makes sure there are no duplicate keys
            if (ContainsKey(key))
            {
                return;
            }

            do
            {
                //calculate index
                int index = _double_hash(key, i);


                if (_table[index].occupied == false)
                {
                    var newEntry = new OAHashEntry(key, value, true);
                    _keys.Add(key);
                    _values.Add(value);

                    //set value and key
                    _table[index] = newEntry;
                    //increment how many items are in the table
                    _inTable++;
                    break;
                }

                i++;

            } while (i != _size);

            //every slot is in the table is occupied
            if (_inTable == _size)
            {
                //expand and rehash
                _expand();
            }
        }

        public void Add(KeyValuePair<TKey, TValue> item)
        {
            Add(item.Key, item.Value);
        }

        //returns value
        public TValue this[TKey key]
        {
            get{
                int index = search(key);

                if (index != -1)
                {
                    return _table[index].value;
                }

                throw new KeyNotFoundException();
            }
            set {

                if (ContainsKey(key) == true)
                {

                    int index = search(key);

                    _table[index].value = value;

                    throw new KeyNotFoundException();

                }
                throw new KeyNotFoundException();
            }
        }


        //removes key-value pair from the table
        public bool Remove(TKey key)
        {

            if (ContainsKey(key))
            {
                //find position and reset values
                int index = search(key);
                _keys.Clear();
                _values.Clear();

                _table[index].key = default(TKey);
                _table[index].value = default(TValue);
                _table[index].occupied = false;

                //number of items in the table decreases
                _inTable--;
                //rehash table --necessary for Open Addressing since keys could have different positions due to this key
                _rehash();

                return true;
            }

            return false;
        }

        //removes key-value pair from the table
        public bool Remove(KeyValuePair<TKey, TValue> item)
        {
            return Remove(item.Key);
        }

        //clears table of all values
        public void Clear()
        {
            _keys.Clear();
            _values.Clear();
            for (int i = 0; i < _table.Length; i++)
            {
                _table[i].key = default(TKey);
                _table[i].value = default(TValue);
                _table[i].occupied = false;
            }
            _inTable = 0;
        }

        //Tries to get the value of key which might not be in the dictionary.
        public bool TryGetValue(TKey key, out TValue value)
        {
            int index = search(key);

            if (index != -1)
            {
                value = _table[index].value;

                return true;
            }

            //not found
            value = default(TValue);
            return false;
        }

        //finds the key and returns index in the table
        public int search(TKey key)
        {
            int i = 0;

            do
            {
                //calculate index
                int index = _double_hash(key, i);
                if (IComparable.Equals(_table[index].key, key))
                {
                    return index;
                }
                i++;

            } while (i < _size);

            return -1;
        }

        //returns true if the key is in the table
        public bool ContainsKey(TKey key)
        {
            if (search(key) != -1)
            {
                return true;
            }
            return false;
        }

        //returns true if the key is in the table
        public bool Contains(KeyValuePair<TKey, TValue> item)
        {
            if (ContainsKey(item.Key))
            {
                return true;
            }

            return false;
        }

        //returns the number of items in the table
        public int Count
        {
            get { return _inTable;}
        }

        //returns bool depending on whether or not the table is read only
        public bool IsReadOnly
        {
            get { return false; }
        }

        //returns a list of keys in the table
        public ICollection<TKey> Keys
        {
            get { return _keys; }
        }

        //returns a list of values in the table
        public ICollection<TValue> Values
        {
            get { return _values; }
        }

        //----------------------------------------------------------------------
        //-----------------------NOT IMPLEMENTED YET----------------------------
        //----------------------------------------------------------------------

        public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
        {
            throw new NotImplementedException();
        }

        public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator()
        {
            throw new NotImplementedException();
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            throw new NotImplementedException();
        }
    }
}

using System;
using System.Collections.Generic;
using DataStructures.Common;

namespace DataStructures.Dictionaries
{
    /// <summary>
    /// Hash Table with Open Addressing (Linear Probing).
    /// </summary>
    public class OpenScatterHashTable<TKey, TValue> : IDictionary<TKey, TValue> where TKey : IComparable<TKey>
    {
        /// <summary>
        /// Hash Table Cell.
        /// </summary>
        private class HashTableEntry
        {
            public TKey Key { get; set; }
            public TValue Value { get; set; }
            public EntryStatus Status { get; set; }

            public HashTableEntry() : this(default(TKey), default(TValue), EntryStatus.Empty) { }
            public HashTableEntry(TKey key, TValue value, EntryStatus status = EntryStatus.Occupied)
            {
                Key = key;
                Value = value;
                Status = status;
            }

            public bool IsEmpty { get { return Status == EntryStatus.Empty; } }
            public bool IsOccupied { get { return Status == EntryStatus.Occupied; } }
            public bool IsDeleted { get { return Status == EntryStatus.Deleted; } }
        }

        /// <summary>
        /// The hash table cell status modes.
        /// </summary>
        private enum EntryStatus { Empty = 0, Occupied = 1, Deleted = 2 }

        // Instance variables
        private int _size;
        private HashTableEntry[] _hashTableStore;
        private const int _defaultCapacity = 7;
        private const double _maxLoadFactor = 0.7;
        private const double _minLoadFactor = 0.2;

        // Comparers
        private readonly EqualityComparer<TKey> _keysComparer;

        // A collection of prime numbers to use as hash table sizes.
        private static readonly PrimesList _primes = PrimesList.Instance;

        /// <summary>
        /// Constructor.
        /// </summary>
        public OpenScatterHashTable()
        {
            _size = 0;
            _hashTableStore = new HashTableEntry[_defaultCapacity];
            _keysComparer = EqualityComparer<TKey>.Default;

            // Initialize all slots as empty
            for (int i = 0; i < _hashTableStore.Length; i++)
                _hashTableStore[i] = new HashTableEntry();
        }

        /// <summary>
        /// Constructor with initial capacity.
        /// </summary>
        public OpenScatterHashTable(int capacity)
        {
            if (capacity < 0)
                throw new ArgumentOutOfRangeException("capacity");

            int actualCapacity = _primes.GetNextPrime(Math.Max(capacity, _defaultCapacity));
            _size = 0;
            _hashTableStore = new HashTableEntry[actualCapacity];
            _keysComparer = EqualityComparer<TKey>.Default;

            for (int i = 0; i < _hashTableStore.Length; i++)
                _hashTableStore[i] = new HashTableEntry();
        }

        /// <summary>
        /// Computes the hash index for a key.
        /// </summary>
        private int _hash(TKey key)
        {
            int hashCode = _keysComparer.GetHashCode(key) & 0x7FFFFFFF;
            return hashCode % _hashTableStore.Length;
        }

        /// <summary>
        /// Finds the slot for a key. Returns the index if found, or -1 if not found.
        /// </summary>
        private int _findSlot(TKey key)
        {
            int index = _hash(key);
            int startIndex = index;

            do
            {
                var entry = _hashTableStore[index];

                if (entry.IsEmpty)
                    return -1; // Key not found

                if (entry.IsOccupied && _keysComparer.Equals(entry.Key, key))
                    return index; // Found

                index = (index + 1) % _hashTableStore.Length;
            }
            while (index != startIndex);

            return -1;
        }

        /// <summary>
        /// Finds a slot for insertion. Returns the index of an empty or deleted slot.
        /// </summary>
        private int _findInsertSlot(TKey key)
        {
            int index = _hash(key);
            int startIndex = index;
            int firstDeletedIndex = -1;

            do
            {
                var entry = _hashTableStore[index];

                if (entry.IsEmpty)
                    return firstDeletedIndex >= 0 ? firstDeletedIndex : index;

                if (entry.IsDeleted && firstDeletedIndex < 0)
                    firstDeletedIndex = index;

                if (entry.IsOccupied && _keysComparer.Equals(entry.Key, key))
                    return index; // Key already exists

                index = (index + 1) % _hashTableStore.Length;
            }
            while (index != startIndex);

            return firstDeletedIndex >= 0 ? firstDeletedIndex : -1;
        }

        /// <summary>
        /// Resizes the hash table.
        /// </summary>
        private void _resize(int newCapacity)
        {
            var oldStore = _hashTableStore;
            _hashTableStore = new HashTableEntry[newCapacity];

            for (int i = 0; i < _hashTableStore.Length; i++)
                _hashTableStore[i] = new HashTableEntry();

            _size = 0;

            // Rehash all existing entries
            foreach (var entry in oldStore)
            {
                if (entry != null && entry.IsOccupied)
                {
                    int index = _findInsertSlot(entry.Key);
                    _hashTableStore[index].Key = entry.Key;
                    _hashTableStore[index].Value = entry.Value;
                    _hashTableStore[index].Status = EntryStatus.Occupied;
                    _size++;
                }
            }
        }

        /// <summary>
        /// Expands the table if load factor is too high.
        /// </summary>
        private void _expandIfNeeded()
        {
            double loadFactor = (double)_size / _hashTableStore.Length;
            if (loadFactor >= _maxLoadFactor)
            {
                int newCapacity = _primes.GetNextPrime(_hashTableStore.Length * 2);
                _resize(newCapacity);
            }
        }

        /// <summary>
        /// Contracts the table if load factor is too low.
        /// </summary>
        private void _contractIfNeeded()
        {
            if (_hashTableStore.Length <= _defaultCapacity)
                return;

            double loadFactor = (double)_size / _hashTableStore.Length;
            if (loadFactor <= _minLoadFactor)
            {
                int newCapacity = _primes.GetNextPrime(_hashTableStore.Length / 2);
                newCapacity = Math.Max(newCapacity, _defaultCapacity);
                _resize(newCapacity);
            }
        }

        #region IDictionary Implementation

        public void Add(TKey key, TValue value)
        {
            if (key == null)
                throw new ArgumentNullException("key");

            _expandIfNeeded();

            int index = _findInsertSlot(key);
            if (index < 0)
                throw new InvalidOperationException("Hash table is full.");

            var entry = _hashTableStore[index];
            if (entry.IsOccupied && _keysComparer.Equals(entry.Key, key))
                throw new ArgumentException("An item with the same key has already been added.", "key");

            _hashTableStore[index].Key = key;
            _hashTableStore[index].Value = value;
            _hashTableStore[index].Status = EntryStatus.Occupied;
            _size++;
        }

        public bool ContainsKey(TKey key)
        {
            if (key == null)
                throw new ArgumentNullException("key");

            return _findSlot(key) >= 0;
        }

        public ICollection<TKey> Keys
        {
            get
            {
                var keys = new List<TKey>(_size);
                foreach (var entry in _hashTableStore)
                {
                    if (entry != null && entry.IsOccupied)
                        keys.Add(entry.Key);
                }
                return keys;
            }
        }

        public bool Remove(TKey key)
        {
            if (key == null)
                throw new ArgumentNullException("key");

            int index = _findSlot(key);
            if (index < 0)
                return false;

            _hashTableStore[index].Status = EntryStatus.Deleted;
            _hashTableStore[index].Key = default(TKey);
            _hashTableStore[index].Value = default(TValue);
            _size--;

            _contractIfNeeded();
            return true;
        }

        public bool TryGetValue(TKey key, out TValue value)
        {
            if (key == null)
                throw new ArgumentNullException("key");

            int index = _findSlot(key);
            if (index >= 0)
            {
                value = _hashTableStore[index].Value;
                return true;
            }

            value = default(TValue);
            return false;
        }

        public ICollection<TValue> Values
        {
            get
            {
                var values = new List<TValue>(_size);
                foreach (var entry in _hashTableStore)
                {
                    if (entry != null && entry.IsOccupied)
                        values.Add(entry.Value);
                }
                return values;
            }
        }

        public TValue this[TKey key]
        {
            get
            {
                if (key == null)
                    throw new ArgumentNullException("key");

                int index = _findSlot(key);
                if (index < 0)
                    throw new KeyNotFoundException("The given key was not present in the dictionary.");

                return _hashTableStore[index].Value;
            }
            set
            {
                if (key == null)
                    throw new ArgumentNullException("key");

                _expandIfNeeded();

                int index = _findInsertSlot(key);
                if (index < 0)
                    throw new InvalidOperationException("Hash table is full.");

                bool isNewEntry = !_hashTableStore[index].IsOccupied || 
                                  !_keysComparer.Equals(_hashTableStore[index].Key, key);

                _hashTableStore[index].Key = key;
                _hashTableStore[index].Value = value;
                _hashTableStore[index].Status = EntryStatus.Occupied;

                if (isNewEntry)
                    _size++;
            }
        }

        #endregion

        #region ICollection Implementation

        public void Add(KeyValuePair<TKey, TValue> item)
        {
            Add(item.Key, item.Value);
        }

        public void Clear()
        {
            _size = 0;
            _hashTableStore = new HashTableEntry[_defaultCapacity];
            for (int i = 0; i < _hashTableStore.Length; i++)
                _hashTableStore[i] = new HashTableEntry();
        }

        public bool Contains(KeyValuePair<TKey, TValue> item)
        {
            int index = _findSlot(item.Key);
            if (index < 0)
                return false;

            return EqualityComparer<TValue>.Default.Equals(_hashTableStore[index].Value, item.Value);
        }

        public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
        {
            if (array == null)
                throw new ArgumentNullException("array");
            if (arrayIndex < 0)
                throw new ArgumentOutOfRangeException("arrayIndex");
            if (array.Length - arrayIndex < _size)
                throw new ArgumentException("The destination array is not large enough.");

            int j = arrayIndex;
            foreach (var entry in _hashTableStore)
            {
                if (entry != null && entry.IsOccupied)
                {
                    array[j++] = new KeyValuePair<TKey, TValue>(entry.Key, entry.Value);
                }
            }
        }

        public int Count
        {
            get { return _size; }
        }

        public bool IsReadOnly
        {
            get { return false; }
        }

        public bool Remove(KeyValuePair<TKey, TValue> item)
        {
            int index = _findSlot(item.Key);
            if (index < 0)
                return false;

            if (!EqualityComparer<TValue>.Default.Equals(_hashTableStore[index].Value, item.Value))
                return false;

            _hashTableStore[index].Status = EntryStatus.Deleted;
            _hashTableStore[index].Key = default(TKey);
            _hashTableStore[index].Value = default(TValue);
            _size--;

            _contractIfNeeded();
            return true;
        }

        #endregion

        #region IEnumerable Implementation

        public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator()
        {
            foreach (var entry in _hashTableStore)
            {
                if (entry != null && entry.IsOccupied)
                {
                    yield return new KeyValuePair<TKey, TValue>(entry.Key, entry.Value);
                }
            }
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using DataStructures.Lists;

namespace DataStructures.Graphs
{
    /// <summary>
    /// Represents an unweighted undirected graph, modeling with a set of its maximal complete subgraphs of it.
    /// Should be fast in clustered graphs
    /// </summary>
    public class CliqueGraph<T> : IGraph<T> where T : IComparable<T>, IEquatable<T>
    {
        public class Clique : HashSet<T>, IComparable<Clique>
        {
            public Clique()
                : base()
            {
            }

            public Clique(ISet<T> elements)
                : base(elements)
            {
            }

            #region IComparable implementation

            int IComparable<Clique>.CompareTo(Clique other)
            {
                throw new NotImplementedException();
            }

            #endregion

            public override string ToString()
            {
                string ret = "{";
                foreach (var x in this)
                {
                    ret += x.ToString() + " ";
                }
                ret += "}";
                return ret;
            }
        }

        #region Model

        /// <summary>
        /// Vertices of the graph.
        /// </summary>
        ICollection<T> _vertices = new HashSet<T>();

        /// <summary>
        /// A set of cliques minimal with the hability of charaterize the graph.
        /// </summary>
        ISet<Clique> _cliques = new HashSet<Clique>();

        #endregion

        #region Constructors

        public CliqueGraph()
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="DataStructures.Graphs.CliqueGraph`1"/> class.
        /// Copies the model from another graph.
        /// </summary>
        /// <param name="graph">Graph.</param>
        public CliqueGraph(IGraph<T> graph)
            : this(graph.Vertices)
        {
            foreach (var startVert in Vertices)
            {
                foreach (var endVert in graph.Neighbours(startVert))
                {
                    if (!HasEdge(startVert, endVert))
                    {
                        // Add vortex
                        Clique newClan = new Clique();
                        newClan.Add(startVert);
                        newClan.Add(endVert);

                        ExpandToMaximal(graph, newClan);
                        _cliques.Add(newClan);
                    }
                }
            }
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="DataStructures.Graphs.CliqueGraph`1"/> class.
        /// </summary>
        /// <param name="vertices">Initial vertices of the graph</param>
        public CliqueGraph(IEnumerable<T> vertices)
            : this()
        {
            if (vertices == null)
            {
                System.Diagnostics.Debug.WriteLine("Cannot initialize an instance of a CliqueGraph with NULL vertices;\ninvoking default constructor.");
            }
            else
            {
                AddVertices(vertices);
            }
        }

        #endregion

        #region Internal

        /// <summary>
        /// Determines if a set of vertices is complete as a subgraph of this
        /// </summary>
        /// <returns><c>true</c>, if the set is a complete subgraph, <c>false</c> otherwise.</returns>
        /// <param name="vertices">A set of vertices of this graph.</param>
        public bool IsComplete(ISet<T> vertices)
        {
            if (!vertices.IsSubsetOf(_vertices))
                throw new Exception("The param in CliqueGraph.IsComplete should be a subset of Vertices");

            /*
	 * vertices is complete iff [vertices]² \subseteq \bigcup_{c \in cliques} [c]²
	 * where [x]² is the set of all subsets of x of cardinality 2.
	*/

            ISet<UnordererPair<T>> H = getPairs(vertices);

            foreach (var clan in _cliques)
            {
                ISet<UnordererPair<T>> exc = getPairs(clan);
                H.ExceptWith(exc);
            }
            return H.Count == 0;
        }

        /// <summary>
        /// Determines if a set of vertices is complete as a subgraph of another graph
        /// </summary>
        /// <returns><c>true</c>, if the set is a complete subgraph, <c>false</c> otherwise.</returns>
        /// <param name="graph">A graph to determine 'completness'</param>
        /// <param name="vertices">A set of vertices of graph.</param>
        static bool IsComplete(IGraph<T> graph, ISet<T> vertices)
        {
            foreach (var x in vertices)
            {
                foreach (var y in vertices)
                {
                    if (!graph.HasEdge(x, y))
                        return false;
                }
            }
            return true;
        }

        /// <summary>
        /// Expands a clique to a maximal complete
        /// </summary>
        /// <param name="clan">Clique to expand</param>
        void ExpandToMaximal(Clique clan)
        {
            Clique maximalityChecker; // Temporal clique for checking maximality

            // Expand NewClique to a maximal complete subgraph
            foreach (var z in Vertices)
            {
                if (!clan.Contains(z))
                {
                    maximalityChecker = new Clique(clan);
                    maximalityChecker.Add(z);
                    if (IsComplete(maximalityChecker))
                        clan.Add(z);
                }
            }

            // Destroy every no maximal elements of the graph
            HashSet<Clique> clone = new HashSet<Clique>(_cliques);
            clone.Remove(clan);
            foreach (var c in clone) // Iterate over a clone of _cliques
            {
                if (clan.IsSupersetOf(c))
                    _cliques.Remove(c);
            }

        }

        /// <summary>
        /// Expands a clique to a maximal complete in a given graph
        /// </summary>
        /// <param name="graph">Graph to use to determine maximality.</param>
        /// <param name="clan">Clique to expand.</param>
        static void ExpandToMaximal(IGraph<T> graph, Clique clan)
        {
            Clique tempo; // Temporal clique for checking maximality
            // Expand NewClique to a maximal complete subgraph
            foreach (var z in graph.Vertices)
            {
                if (!clan.Contains(z))
                {
                    tempo = new Clique(clan);
                    tempo.Add(z);
                    if (IsComplete(graph, tempo))
                        clan.Add(z);
                }
            }
        }

        /// <summary>
        /// Some (temporary) class to compare unorderer pairs.
        /// </summary>
        class PairComparer : IEqualityComparer<UnordererPair<T>>
        {
            #region IEqualityComparer implementation

            bool IEqualityComparer<UnordererPair<T>>.Equals(UnordererPair<T> x, UnordererPair<T> y)
            {
                return ((IEquatable<UnordererPair<T>>)x).Equals(y);
            }

            int IEqualityComparer<UnordererPair<T>>.GetHashCode(UnordererPair<T> obj)
            {
                return obj.Item1.GetHashCode() + obj.Item2.GetHashCode();
            }

            #endregion

        }

        /// <summary>
        /// Return the subsets of cardinality 2 of a given collection. ie [vertices]².
        /// </summary>
        /// <returns>Returns an ISet whose elements are every subset of a given set of cardinality 2.</returns>
        /// <param name="vertices">Collection whose pairs are going to be returned.</param>
        ISet<UnordererPair<T>> getPairs(ICollection<T> vertices)
        {
            T[] arr = new T[vertices.Count];
            ISet<UnordererPair<T>> ret = new System.Collections.Generic.HashSet<UnordererPair<T>>(new PairComparer());
            vertices.CopyTo(arr, 0);
            for (int i = 0; i < vertices.Count; i++)
            {
                for (int j = i + 1; j < vertices.Count; j++)
                {
                    ret.Add(new UnordererPair<T>(arr[i], arr[j]));
                }
            }
            return ret;
        }

        #endregion


        #region IGraph implementation

        /// <summary>
        /// An enumerable collection of all graph edges.
        /// </summary>
        public IEnumerable<IEdge<T>> Edges
        {
            get
            {
                List<UnweightedEdge<T>> returnEdges = new List<UnweightedEdge<T>>();

                foreach (var edge in getEdges())
                {
                    returnEdges.Add(new UnweightedEdge<T>(edge.Item1, edge.Item2));
                    returnEdges.Add(new UnweightedEdge<T>(edge.Item2, edge.Item1));
                }
                return returnEdges;
            }
        }

        /// <summary>
        /// Get all incoming edges to vertex.
        /// </summary>
        public IEnumerable<IEdge<T>> IncomingEdges(T vertex)
        {
            List<UnweightedEdge<T>> incomingEdges = new List<UnweightedEdge<T>>();

            foreach (var c in _cliques)
            {
                if (c.Contains(vertex))
                {
                    foreach (var item in c)
                    {
                        if (!incomingEdges.Exists(x => x.Source.Equals(item)))
                            incomingEdges.Add(new UnweightedEdge<T>(item, vertex));
                    }
                }
            }

            return incomingEdges;

        }

        /// <summary>
        /// Get all outgoing edges from a vertex.
        /// </summary>
        public IEnumerable<IEdge<T>> OutgoingEdges(T vertex)
        {
            List<UnweightedEdge<T>> outgoingEdges = new List<UnweightedEdge<T>>();

            foreach (var c in _cliques)
            {
                if (c.Contains(vertex))
                {
                    foreach (var item in c)
                    {
                        if (!outgoingEdges.Exists(x => x.Destination.Equals(item)))
                            outgoingEdges.Add(new UnweightedEdge<T>(vertex, item));
                    }
                }
            }

            return outgoingEdges;
        }

        /// <summary>
        /// Connects two vertices together.
        /// </summary>
        /// <returns><c>true</c>, if edge was added, <c>false</c> otherwise.</returns>
        /// <param name="firstVertex">First vertex.</param>
        /// <param name="secondVertex">Second vertex.</param>
        public bool AddEdge(T firstVertex, T secondVertex)
        {
            if (HasEdge(firstVertex, secondVertex))
                return false;
            Clique NewClique = new Clique();  // The new clique that contains the edge (firstVertex, secondVertex)
            _cliques.Add(NewClique);

            _vertices.Add(firstVertex);
            _vertices.Add(secondVertex);

            NewClique.Add(firstVertex);
            NewClique.Add(secondVertex);

            ExpandToMaximal(NewClique);
            return true;
        }

        /// <summary>
        /// Deletes an edge, if exists, between two vertices.
        /// </summary>
        /// <returns><c>true</c>, if edge was removed, <c>false</c> otherwise.</returns>
        /// <param name="firstVertex">First vertex.</param>
        /// <param name="secondVertex">Second vertex.</param>
        public bool RemoveEdge(T firstVertex, T secondVertex)
        {
            bool ret = false;
            Clique splitting;
            Clique removing = new Clique();
            removing.Add(firstVertex);
            removing.Add(secondVertex);

            foreach (var clan in new HashSet<Clique>(_cliques))  //Iterating over a clone of cliques
            {
                if (clan.IsSupersetOf(removing))
                {
                    // clan should be eliminated from cliques and replaced by maximal refinements
                    _cliques.Remove(clan);

                    splitting = new Clique(clan);
                    splitting.Remove(firstVertex);
                    _cliques.Add(splitting);
                    ExpandToMaximal(splitting);

                    splitting = new Clique(clan);
                    splitting.Remove(secondVertex);
                    _cliques.Add(splitting);
                    ExpandToMaximal(splitting);

                    ret = true;  // return true when finished
                }
            }
            return ret;
        }

        /// <summary>
        /// Adds a list of vertices to the graph.
        /// </summary>
        /// <param name="collection">Collection.</param>
        public void AddVertices(IEnumerable<T> collection)
        {
            if (collection == null)
                throw new ArgumentException();

            foreach (var vertex in collection)
            {
                AddVertex(vertex);
            }
        }

        /// <summary>
        /// Adds a list of vertices to the graph.
        /// </summary>
        /// <param name="collection">Collection.</param>
        void IGraph<T>.AddVertices(IList<T> collection)
        {
            AddVertices(collection);
        }

        /// <summary>
        /// Adds a new vertex to graph.
        /// </summary>
        /// <returns><c>true</c>, if vertex was added, <c>false</c> otherwise.</returns>
        /// <param name="vertex">Vertex.</param>
        public bool AddVertex(T vertex)
        {
            bool ret = !_vertices.Contains(vertex);
            _vertices.Add(vertex);
            return ret;
        }

        /// <summary>
        /// Removes the specified vertex from graph.
        /// </summary>
        /// <returns><c>true</c>, if vertex was removed, <c>false</c> otherwise.</returns>
        /// <param name="vertex">Vertex.</param>
        public bool RemoveVertex(T vertex)
        {
            // Remove vertex from set of vertices, return false if nothing was removed.
            if (!_vertices.Remove(vertex))
                return false;

            // Make the cliques consistent
            foreach (var clan in new HashSet<Clique>(_cliques)) // clone _cliques and iterate
            {
                if (clan.Remove(vertex))
                {
                    // if clan was exhausted, remove it;
                    if (clan.Count <= 1)
                    {
                        _cliques.Remove(clan);
                    }
                    else // else make it maximal
                    {
                        ExpandToMaximal(clan);
                    }
                }
            }
            return true;
        }

        /// <summary>
        /// Determines whether this instance has edge the specified firstVertex secondVertex.
        /// </summary>
        /// <returns><c>true</c> if this instance has edge the specified firstVertex secondVertex; otherwise, <c>false</c>.</returns>
        /// <param name="firstVertex">First vertex.</param>
        /// <param name="secondVertex">Second vertex.</param>
        public bool HasEdge(T firstVertex, T secondVertex)
        {
            ISet<T> edge = new HashSet<T>();
            edge.Add(firstVertex);
            edge.Add(secondVertex);

            // If [edge]² (= edge) is contained in some clan, there is an edge.
            foreach (var clan in _cliques)
            {
                if (clan.IsSupersetOf(edge))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// Determines whether this graph has the specified vertex.
        /// </summary>
        /// <returns><c>true</c> if this instance has vertex the specified vertex; otherwise, <c>false</c>.</returns>
        /// <param name="vertex">Vertex.</param>
        public bool HasVertex(T vertex)
        {
            return _vertices.Contains(vertex);
        }

        /// <summary>
        /// Returns the neighbours doubly-linked list for the specified vertex.
        /// </summary>
        /// <param name="vertex">Vertex.</param>
        public DataStructures.Lists.DLinkedList<T> Neighbours(T vertex)
        {
            DataStructures.Lists.DLinkedList<T> returnList = new DataStructures.Lists.DLinkedList<T>();

            foreach (var c in _cliques)
            {
                if (c.Contains(vertex))
                {
                    foreach (var item in c)
                    {
                        if (!returnList.Contains(item))
                            returnList.Append(item);
                    }
                }
            }

            return returnList;
        }

        public int Degree(T vertex)
        {
            return Neighbours(vertex).Count;
        }

