        /// <summary>
        /// Returns the list of edges.
        /// </summary>
        /// <returns></returns>
        ICollection<UnordererPair<T>> getEdges()
        {
            ISet<UnordererPair<T>> H = new HashSet<UnordererPair<T>>();

            foreach (var clan in _cliques)
            {
                ISet<UnordererPair<T>> union = getPairs(clan);
                H.UnionWith(union);
            }
            return H;
