    /// <summary>
    /// Singly Linked List Data Structure
    /// </summary>
    public class SLinkedList<T> : IEnumerable<T> where T : IComparable<T>
    {
        /// <summary>
        /// Instance variables
        /// </summary>
        private int _count;
        private SLinkedListNode<T> _firstNode { get; set; }
        private SLinkedListNode<T> _lastNode { get; set; }

        public int Count
        {
            get { return _count; }
        }

        public virtual SLinkedListNode<T> Head
        {
            get { return this._firstNode; }
        }

        /// <summary>
        /// CONSTRUCTOR
        /// </summary>
        public SLinkedList()
        {
            _firstNode = null;
            _lastNode = null;
            _count = 0;
        }

        /// <summary>
        /// The Is List Empty check.
        /// </summary>
        /// <returns>true, if the list is empty, false otherwise.</returns>
        public bool IsEmpty()
        {
            return (Count == 0);
        }

        /// <summary>
        /// Getter function that returns the first element
        /// </summary>
        public T First
        {
            get
            {
                return (_firstNode == null ? default(T) : _firstNode.Data);
            }
        }

        /// <summary>
        /// Getter function that returns the last element
        /// </summary>
        public T Last
        {
            get
            {
                if (Count == 0)
                {
                    throw new Exception("Empty list.");
                }

                if (_lastNode == null)
                {
                    var currentNode = _firstNode;
                    while (currentNode.Next != null)
                    {
                        currentNode = currentNode.Next;
                    }
                    _lastNode = currentNode;
                    return currentNode.Data;
                }

                return _lastNode.Data;
            }
        }

        /// <summary>
        /// Inserts the specified dataItem at the beginning of the list.
        /// </summary>
        /// <param name="dataItem">The data value to be inserted to the list.</param>
        public void Prepend(T dataItem)
        {
            SLinkedListNode<T> newNode = new SLinkedListNode<T>(dataItem);

            if (_firstNode == null)
            {
                _firstNode = _lastNode = newNode;
            }
            else
            {
                var currentNode = _firstNode;
                newNode.Next = currentNode;
                _firstNode = newNode;
            }

            // Increment the count.
            _count++;
        }

        /// <summary>
        /// Inserts the specified dataItem at the end of the list.
        /// </summary>
        /// <param name="dataItem">The data value to be inserted to the list.</param>
        public void Append(T dataItem)
        {
            SLinkedListNode<T> newNode = new SLinkedListNode<T>(dataItem);

            if (_firstNode == null)
            {
                _firstNode = _lastNode = newNode;
            }
            else
            {
                var currentNode = _lastNode;
                currentNode.Next = newNode;
                _lastNode = newNode;
            }

            // Increment the count.
            _count++;
        }

        /// <summary>
        /// Inserts a specified item dataItem at an index.
        /// </summary>
        /// <param name="dataItem">Data item.</param>
        /// <param name="index">Index.</param>
        public void InsertAt(T dataItem, int index)
        {
            // Handle scope of insertion.
            // Prepend? Append? Or Insert in the range?
            if (index == 0)
            {
                Prepend(dataItem);
            }
            else if (index == Count)
            {
                Append(dataItem);
            }
            else if (index > 0 && index < Count)
            {
                var currentNode = _firstNode;
                var newNode = new SLinkedListNode<T>(dataItem);

                for (int i = 1; i < index; ++i)
                {
                    currentNode = currentNode.Next;
                }

                newNode.Next = currentNode.Next;
                currentNode.Next = newNode;

                // Increment the count
                _count++;
            }
            else
            {
                throw new IndexOutOfRangeException();
            }
        }

        /// <summary>
        /// Removes the item at the specified index.
        /// </summary>
        /// <param name="index">The index of the list node to be removed.</param>
        public void RemoveAt(int index)
        {
            // Handle index out of bound errors
            if (IsEmpty() || index < 0 || index >= Count)
                throw new IndexOutOfRangeException();

            // Remove
            if (index == 0)
            {
                _firstNode = _firstNode.Next;

                // Decrement count.
                _count--;
            }
            else if (index == Count - 1)
            {
                var currentNode = _firstNode;

                while (currentNode.Next != null && currentNode.Next != _lastNode)
                    currentNode = currentNode.Next;

                currentNode.Next = null;
                _lastNode = currentNode;

                // Decrement count.
                _count--;
            }
            else
            {
                int i = 0;
                var currentNode = _firstNode;
                while (currentNode.Next != null)
                {
                    if (i + 1 == index)
                    {
                        currentNode.Next = currentNode.Next.Next;

                        // Decrement the count.
                        _count--;
                        break;
                    }

                    ++i;
                    currentNode = currentNode.Next;
                }
            }
        }

        /// <summary>
        /// Clears all the items in the list.
        /// </summary>
        public void Clear()
        {
            _firstNode = null;
            _lastNode = null;
            _count = 0;
        }

        /// <summary>
        /// Get the element at the specified index
        /// </summary>
        /// <param name="index">Index of element</param>
        /// <returns>Element</returns>
        public T GetAt(int index)
        {
            if (index == 0)
            {
                return First;
            }

            if (index == (Count - 1))
            {
                return Last;
            }

            if (index > 0 && index < (Count - 1))
            {
                var currentNode = _firstNode;
                for (int i = 0; i < index; ++i)
                {
                    currentNode = currentNode.Next;
                }
                return currentNode.Data;
            }

            throw new IndexOutOfRangeException();
        }

        /// <summary>
        /// Returns a number of elements as specified by countOfElements, starting from the specified index.
        /// </summary>
        /// <param name="index">Starting index.</param>
        /// <param name="countOfElements">The number of elements to return.</param>
        /// <returns>Singly-Linked List of elements</returns>
        public SLinkedList<T> GetRange(int index, int countOfElements)
        {
            SLinkedList<T> newList = new SLinkedList<T>();
            var currentNode = this._firstNode;

            // Handle Index out of Bound errors
            if (Count == 0)
            {
                return newList;
            }

            if (index < 0 || index > Count)
            {
                throw new IndexOutOfRangeException();
            }

            // Move the currentNode reference to the specified index
            for (int i = 0; i < index; ++i)
            {
                currentNode = currentNode.Next;
            }

            // Append the elements to the new list using the currentNode reference
            while (currentNode != null && newList.Count <= countOfElements)
            {
                newList.Append(currentNode.Data);
                currentNode = currentNode.Next;
            }

            return newList;
        }

        /// <summary>
        /// Sorts the entire list using Selection Sort.
        /// </summary>
        public virtual void SelectionSort()
        {
            if (IsEmpty())
                return;

            var currentNode = _firstNode;
            while (currentNode != null)
            {
                var minNode = currentNode;
                var nextNode = currentNode.Next;
                while (nextNode != null)
                {
                    if (nextNode.Data.IsLessThan(minNode.Data))
                    {
                        minNode = nextNode;
                    }

                    nextNode = nextNode.Next;
                }

                if (minNode != currentNode)
                {
                    var temp = minNode.Data;
                    minNode.Data = currentNode.Data;
                    currentNode.Data = temp;
                }
                currentNode = currentNode.Next;
            }
        }

        /// <summary>
        /// Return an array version of this list.
        /// </summary>
        /// <returns></returns>
        public T[] ToArray()
        {
            T[] array = new T[Count];

            var currentNode = _firstNode;
            for (int i = 0; i < Count; ++i)
            {
                if (currentNode != null)
                {
                    array[i] = currentNode.Data;
                    currentNode = currentNode.Next;
                }
                else
                {
                    break;
                }
            }

            return array;
        }

        /// <summary>
        /// Returns a System.List version of this SLinkedList instace.
        /// </summary>
        /// <returns>System.List of elements</returns>
        public List<T> ToList()
        {
            List<T> list = new List<T>();

            var currentNode = _firstNode;
            for (int i = 0; i < Count; ++i)
            {
                if (currentNode != null)
                {
                    list.Add(currentNode.Data);
                    currentNode = currentNode.Next;
                }
                else
                {
                    break;
                }
            }

            return list;
        }

        /// <summary>
        /// Returns the list items as a readable multi--line string.
        /// </summary>
        /// <returns></returns>
        public string ToReadable()
        {
            int i = 0;
            var currentNode = _firstNode;
            string listAsString = string.Empty;

            while (currentNode != null)
            {
                listAsString = String.Format("{0}[{1}] => {2}\r\n", listAsString, i, currentNode.Data);
                currentNode = currentNode.Next;
                ++i;
            }

            return listAsString;
        }

        /********************************************************************************/

        public IEnumerator<T> GetEnumerator()
        {
            return new SLinkedListEnumerator(this);
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return new SLinkedListEnumerator(this);
        }

        /********************************************************************************/

        internal class SLinkedListEnumerator : IEnumerator<T>
        {
            private SLinkedListNode<T> _current;
            private SLinkedList<T> _doublyLinkedList;

            public SLinkedListEnumerator(SLinkedList<T> list)
            {
                this._doublyLinkedList = list;
                this._current = list.Head;
            }

            public T Current
            {
                get { return this._current.Data; }
            }

            object System.Collections.IEnumerator.Current
            {
                get { return Current; }
            }

            public bool MoveNext()
            {
                _current = _current.Next;

                return (this._current != null);
            }

            public void Reset()
            {
                _current = _doublyLinkedList.Head;
            }

            public void Dispose()
            {
                _current = null;
                _doublyLinkedList = null;
            }
        }
    }

}

/***
 * The Skip-List data structure implementation. 
 * 
 * Uses the custom class SkipListNode<T>.
 * 
 * Note: A more memory efficient implementation would use structs, but this is the simplest implementation possible.
 */

using System;
using System.Collections.Generic;
using DataStructures.Common;

namespace DataStructures.Lists
{
    /// <summary>
    /// THE SKIP-LIST DATA STRUCTURE
    /// </summary>
    public class SkipList<T> : ICollection<T>, IEnumerable<T> where T : IComparable<T>
    {
        private int _count { get; set; }
        private int _currentMaxLevel { get; set; }
        private Random _randomizer { get; set; }

        // The skip-list root node
        private SkipListNode<T> _firstNode { get; set; }

        // Readonly values
        private readonly int MaxLevel = 32;
        private readonly double Probability = 0.5;


        /// <summary>
        /// Private helper. Used in Add method.
        /// Returns a random level for a new node. Level is at least 1.
        /// </summary>
        /// <returns>A random level between 1 and MaxLevel</returns>
        private int _getNextLevel()
        {
            // BUG FIX: Start at 1, not 0. A node with level 0 would have an empty
            // Forwards array and would never be linked into the skip list.
            // See: https://github.com/aalhour/C-Sharp-Algorithms/issues/137
            int lvl = 1;

            while (_randomizer.NextDouble() < Probability && lvl < _currentMaxLevel && lvl < MaxLevel)
                ++lvl;

            return lvl;
        }


        /// <summary>
        /// CONSTRUCTOR
        /// </summary>
        public SkipList()
        {
            _count = 0;
            _currentMaxLevel = 1;
            _randomizer = new Random();
            _firstNode = new SkipListNode<T>(default(T), MaxLevel);

            for (int i = 0; i < MaxLevel; ++i)
                _firstNode.Forwards[i] = _firstNode;
        }


        /// <summary>
        /// Getter accessor for the first node
        /// </summary>
        public SkipListNode<T> Root
        {
            get { return _firstNode; }
        }

        /// <summary>
        /// Checks if list is empty or not
        /// </summary>
        public bool IsEmpty
        {
            get { return Count == 0; }
        }

        /// <summary>
        /// Return count of elements
        /// </summary>
        public int Count
        {
            get { return _count; }
        }

        /// <summary>
        /// Return current max-node level
        /// </summary>
        public int Level
        {
            get { return _currentMaxLevel; }
        }

        /// <summary>
        /// Access elements by index
        /// </summary>
        public T this[int index]
        {
            get
            {
                // TODO:
                throw new NotImplementedException();
            }
        }

        /// <summary>
        /// Adds item to the list
        /// </summary>
        public void Add(T item)
        {
            var current = _firstNode;
            var toBeUpdated = new SkipListNode<T>[MaxLevel];

            for (int i = _currentMaxLevel - 1; i >= 0; --i)
            {
                while (current.Forwards[i] != _firstNode && current.Forwards[i].Value.IsLessThan(item))
                    current = current.Forwards[i];

                toBeUpdated[i] = current;
            }

            current = current.Forwards[0];

            // Get the next node level, and update list level if required.
            int lvl = _getNextLevel();
            if (lvl > _currentMaxLevel)
            {
                for (int i = _currentMaxLevel; i < lvl; ++i)
                    toBeUpdated[i] = _firstNode;

                _currentMaxLevel = lvl;
            }

            // New node
            var newNode = new SkipListNode<T>(item, lvl);

            // Insert the new node into the skip list
            for (int i = 0; i < lvl; ++i)
            {
                newNode.Forwards[i] = toBeUpdated[i].Forwards[i];
                toBeUpdated[i].Forwards[i] = newNode;
            }

            // Increment the count
            ++_count;
        }

        /// <summary>
        /// Remove element from the list.
        /// </summary>
        public bool Remove(T item)
        {
            T deleted;
            return Remove(item, out deleted);
        }

        /// <summary>
        /// Remove an element from list and then return it
        /// </summary>
        public bool Remove(T item, out T deleted)
        {
            // Find the node in each of the levels
            var current = _firstNode;
            var toBeUpdated = new SkipListNode<T>[MaxLevel];

            // Walk after all the nodes that have values less than the node we are looking for.
            // Mark all nodes as toBeUpdated.
            for (int i = _currentMaxLevel - 1; i >= 0; --i)
            {
                while (current.Forwards[i] != _firstNode && current.Forwards[i].Value.IsLessThan(item))
                    current = current.Forwards[i];

                toBeUpdated[i] = current;
            }

            current = current.Forwards[0];

            // BUG FIX: Don't match the sentinel node (_firstNode).
            // The sentinel has default(T) as its value, which could match user queries.
            // See: https://github.com/aalhour/C-Sharp-Algorithms/issues/139
            if (current == _firstNode)
            {
                deleted = default(T);
                return false;
            }

            // Return default value of T if the item was not found
            if (current.Value.IsEqualTo(item) == false)
            {
                deleted = default(T);
                return false;
            }

            // We know that the node is in the list.
            // Unlink it from the levels where it exists.
            for (int i = 0; i < _currentMaxLevel; ++i)
                if (toBeUpdated[i].Forwards[i] == current)
                    toBeUpdated[i].Forwards[i] = current.Forwards[i];

            // Decrement the count
            --_count;

            // Check to see if we've deleted the highest-level node
            // Decrement level
            while (_currentMaxLevel > 1 && _firstNode.Forwards[_currentMaxLevel - 1] == _firstNode)
                --_currentMaxLevel;

            // Assign the deleted output parameter to the node.Value
            deleted = current.Value;
            return true;
        }

        /// <summary>
        /// Checks if an item is in the list
        /// </summary>
        public bool Contains(T item)
        {
            T itemOut;
            return Find(item, out itemOut);
        }

        /// <summary>
        /// Look for an element and return it if found
        /// </summary>
        public bool Find(T item, out T result)
        {
            var current = _firstNode;

            // Walk after all the nodes that have values less than the node we are looking for
            for (int i = _currentMaxLevel - 1; i >= 0; --i)
                while (current.Forwards[i] != _firstNode && current.Forwards[i].Value.IsLessThan(item))
                    current = current.Forwards[i];

            current = current.Forwards[0];

            // BUG FIX: Don't match the sentinel node (_firstNode).
            // The sentinel has default(T) as its value, which could match user queries
            // (e.g., 0 for int, null for reference types).
            // See: https://github.com/aalhour/C-Sharp-Algorithms/issues/138
            if (current == _firstNode)
            {
                result = default(T);
                return false;
            }

            // Return true if we found the element; false otherwise
            if (current.Value.IsEqualTo(item))
            {
                result = current.Value;
                return true;
            }

            result = default(T);
            return false;
        }

        /// <summary>
        /// Deletes the min element if the list is empty; otherwise throws exception
        /// </summary>
        public T DeleteMin()
        {
            T min;

            if (!TryDeleteMin(out min))
            {
                throw new InvalidOperationException("SkipList is empty.");
            }

            return min;
        }

        /// <summary>
        /// Tries to delete the min element, returns false if list is empty
        /// </summary>
        public bool TryDeleteMin(out T result)
        {
            if (IsEmpty)
            {
                result = default(T);
                return false;
            }

            return Remove(_firstNode.Forwards[0].Value, out result);
        }

        /// <summary>
        /// Returns the first element if the list is not empty; otherwise throw an exception
        /// </summary>
        public T Peek()
        {
            T peek;

            if (!TryPeek(out peek))
            {
                throw new InvalidOperationException("SkipList is empty.");
            }

            return peek;
        }

        /// <summary>
        /// Tries to return the first element, if the list is empty it returns false
        /// </summary>
        public bool TryPeek(out T result)
        {
            if (IsEmpty)
            {
                result = default(T);
                return false;
            }

            result = _firstNode.Forwards[0].Value;
            return true;
        }


        #region IEnumerable<T> Implementation
        /// <summary>
        /// IEnumerable method implementation
        /// </summary>
        public IEnumerator<T> GetEnumerator()
        {
            var node = _firstNode;
            while (node.Forwards[0] != null && node.Forwards[0] != _firstNode)
            {
                node = node.Forwards[0];
                yield return node.Value;
            }
        }

        /// <summary>
        /// IEnumerable method implementation
        /// </summary>
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
        #endregion IEnumerable<T> Implementation


        #region ICollection<T> Implementation
        /// <summary>
        /// Checks whether this collection is readonly
        /// </summary>
        public bool IsReadOnly
        {
            get { return false; }
        }

        /// <summary>
        /// Copy this list to an array
        /// </summary>
        public void CopyTo(T[] array, int arrayIndex)
        {
            // Validate the array and arrayIndex
            if (array == null)
                throw new ArgumentNullException();
            if (array.Length == 0 || arrayIndex >= array.Length || arrayIndex < 0)
                throw new IndexOutOfRangeException();

            // Get enumerator
            var enumarator = this.GetEnumerator();

            // Copy elements as long as there is any in the list and as long as the index is within the valid range
            for (int i = arrayIndex; i < array.Length; ++i)
            {
                if (enumarator.MoveNext())
                    array[i] = enumarator.Current;
                else
                    break;
            }
        }

        /// <summary>
        /// Clears this instance
        /// </summary>
        public void Clear()
        {
            _count = 0;
            _currentMaxLevel = 1;
            _randomizer = new Random();
            _firstNode = new SkipListNode<T>(default(T), MaxLevel);

            for (int i = 0; i < MaxLevel; ++i)
                _firstNode.Forwards[i] = _firstNode;
        }
        #endregion

    }

}

using System;

namespace DataStructures.Lists
{
    public class SkipListNode<T> : IComparable<SkipListNode<T>> where T : IComparable<T>
    {
        /// <summary>
        /// Instance variables
        /// </summary>
        private T _value;
        private SkipListNode<T>[] _forwards;

        /// <summary>
        /// CONSTRUCTORS
        /// </summary>
        public SkipListNode(T value, int level)
        {
            if (level < 0)
                throw new ArgumentOutOfRangeException("Invalid value for level.");

            Value = value;
            Forwards = new SkipListNode<T>[level];
        }

        /// <summary>
        /// Get and set node's value
        /// </summary>
        public virtual T Value
        {
            get { return this._value; }
            private set { this._value = value; }
        }

        /// <summary>
        /// Get and set node's forwards links
        /// </summary>
        public virtual SkipListNode<T>[] Forwards
        {
            get { return this._forwards; }
            private set { this._forwards = value; }
        }

        /// <summary>
        /// Return level of node.
        /// </summary>
        public virtual int Level
        {
            get { return Forwards.Length; }
        }

        /// <summary>
        /// IComparable method implementation
        /// </summary>
        public int CompareTo(SkipListNode<T> other)
        {
            if (other == null)
                return -1;

            return this.Value.CompareTo(other.Value);
        }
    }
}

using System;
using System.Collections.Generic;

namespace DataStructures.Lists
{
    /// <summary>
    /// The Stack (LIFO) Data Structure.
    /// </summary>
    /// <typeparam name="T">Type</typeparam>
    public class Stack<T> : IEnumerable<T> where T : IComparable<T>
    {
        /// <summary>
        /// Instance variables.
        /// _collection: Array-Based List.
        /// Count: Public Getter for returning the number of elements.
        /// </summary>
        private ArrayList<T> _collection { get; set; }
        public int Count { get { return _collection.Count; } }


        /// <summary>
        /// CONSTRUCTORS
        /// </summary>
        public Stack()
        {
            // The internal collection is implemented as an array-based list.
            // See the ArrayList.cs for the list implementation.
            _collection = new ArrayList<T>();
        }


        public Stack(int initialCapacity)
        {
            if (initialCapacity < 0)
            {
                throw new ArgumentOutOfRangeException();
            }

            // The internal collection is implemented as an array-based list.
            // See the ArrayList.cs for the list implementation.
            _collection = new ArrayList<T>(initialCapacity);
        }


        /// <summary>
        /// Checks whether the stack is empty.
        /// </summary>
        /// <returns>True if stack is empty, false otherwise.</returns>
        public bool IsEmpty
        {
            get
            {
                return _collection.IsEmpty;
            }
        }


        /// <summary>
        /// Returns the top element in the stack.
        /// </summary>
        public T Top
        {
            get
            {
                try
                {
                    return _collection[_collection.Count - 1];
                }
                catch (Exception)
                {
                    throw new Exception("Stack is empty.");
                }
            }
        }


        /// <summary>
        /// Inserts an element at the top of the stack.
        /// </summary>
        /// <param name="dataItem">Element to be inserted.</param>
        public void Push(T dataItem)
        {
            _collection.Add(dataItem);
        }


        /// <summary>
        /// Removes the top element from stack.
        /// </summary>
        public T Pop()
        {
            if (Count > 0)
            {
                var top = Top;
                _collection.RemoveAt(_collection.Count - 1);
                return top;
            }

            throw new Exception("Stack is empty.");
        }

        /// <summary>
        /// Returns an array version of this stack.
        /// </summary>
        /// <returns>System.Array.</returns>
        public T[] ToArray()
        {
            return _collection.ToArray();
        }


        /// <summary>
        /// Returns a human-readable, multi-line, print-out (string) of this stack.
        /// </summary>
        /// <returns>String.</returns>
        public string ToHumanReadable()
        {
            return _collection.ToHumanReadable();
        }


        /********************************************************************************/


        public IEnumerator<T> GetEnumerator()
        {
            for (int i = _collection.Count - 1; i >= 0; --i)
                yield return _collection[i];
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return this.GetEnumerator();
        }

    }

}

using System;
using System.Collections.Generic;

using DataStructures.Trees;

namespace DataStructures.SortedCollections
{
    /// <summary>
    /// Sorted Dictionary collection (Red-Black Tree based).
    /// </summary>
    public class SortedDictionary<TKey, TValue> : IEnumerable<KeyValuePair<TKey, TValue>>, IDictionary<TKey, TValue> 
        where TKey : IComparable<TKey>
    {
        /// <summary>
        /// The internal collection is a Red-Black Tree Map.
        /// </summary>
        private RedBlackTreeMap<TKey, TValue> _collection { get; set; }


        /// <summary>
        /// Constructor.
        /// </summary>
        public SortedDictionary()
        {
            _collection = new RedBlackTreeMap<TKey, TValue>(allowDuplicates: false);
        }


        /// <summary>
        /// Gets the count of enteries in dictionary.
        /// </summary>
        public int Count
        {
            get { return _collection.Count; }
        }

        /// <summary>
        /// Returns true if dictionary is empty; otherwise, false.
        /// </summary>
        public bool IsEmpty
        {
            get { return Count == 0; }
        }

        public bool IsReadOnly
        {
            get { return false; }
        }

        /// <summary>
        /// Determines whether the current dictionary contains an entry with the specified key.
        /// </summary>
        public bool ContainsKey(TKey key)
        {
            return _collection.Contains(key);
        }

        /// <summary>
        /// Determines whether the current collection contains a specific key-value pair.
        /// </summary>
        public bool Contains(KeyValuePair<TKey, TValue> item)
        {
            try
            {
                var entry = _collection.Find(item.Key);
                return entry.Value.Equals(item.Value);
            }
            catch(Exception)
            {
                return false;
            }
        }

        /// <summary>
        /// Try to get the value of a key or default(TValue). Returns true if key exists; otherwise, false.
        /// </summary>
        public bool TryGetValue(TKey key, out TValue value)
        {
            // Set value to the default value of type TValue
            value = default(TValue);

            try
            {
                // Assign the returned object to value
                value = _collection.Find(key).Value;

                // return Success.
                return true;
            }
            catch(KeyNotFoundException)
            {
                // No entry was found with the specified key.
                // return Failure.
                return false;
            }
        }

        /// <summary>
        /// Gets or sets the value at the specified key.
        /// </summary>
        public TValue this[TKey index]
        {
            get
            {
                // In case dictionary is empty
                if (IsEmpty)
                    throw new Exception("Dictionary is empty.");

                try
                {
                    return _collection.Find(index).Value;
                }
                catch(KeyNotFoundException)
                {
                    // Mask the tree's exception with a new one.
                    throw new KeyNotFoundException("Key doesn't exist in dictionary.");
                }
            }
            set
            {
                if (ContainsKey(index))
                    _collection.Update(index, value);
                else
                    Add(index, value);
            }
        }

        /// <summary>
        /// Gets the collection of keys in the dictionary.
        /// </summary>
        public ICollection<TKey> Keys
        {
            get
            {
                var keys = new System.Collections.Generic.List<TKey>(Count);
                var enumerator = _collection.GetInOrderEnumerator();

                while (enumerator.MoveNext())
                    keys.Add(enumerator.Current.Key);

                return keys;
            }
        }

        /// <summary>
        /// Gets the collection of values in the dictionary.
        /// </summary>
        public ICollection<TValue> Values
        {
            get
            {
                var values = new System.Collections.Generic.List<TValue>(Count);
                var enumerator = _collection.GetInOrderEnumerator();

                while (enumerator.MoveNext())
                    values.Add(enumerator.Current.Value);

                return values;
            }
        }

        /// <summary>
        /// Add the specified key and value to the dictionary.
        /// </summary>
        public void Add(TKey key, TValue value)
        {
            // Throw an duplicate key exception if an entry with the same key exists
            try
            {
                _collection.Insert(key, value);
            }
            catch(InvalidOperationException)
            {
                throw new InvalidOperationException("An entry with the same key already exists in dictionary.");
            }
        }

        /// <summary>
        /// Removes the item with specific Key from the dictionary.
        /// </summary>
        public bool Remove(TKey key)
        {
            try
            {
                // Try removing it and return Success
                _collection.Remove(key);
                return true;
            }
            catch(Exception)
            {
                // Item was not found. Return Failure.
                return false;
            }
        }

        /// <summary>
        /// Add the key-value pair to the dictionary.
        /// </summary>
        public void Add(KeyValuePair<TKey, TValue> item)
        {
            Add(item.Key, item.Value);
        }

        /// <summary>
        /// Removes the first occurrence of an item from the current collection Key and Value will be matched.
        /// </summary>
        public bool Remove(KeyValuePair<TKey, TValue> item)
        {
            if (IsEmpty)
                return false;

            // Get the entry from collection
            var entry = _collection.Find(item.Key);

            // If the entry's value match the value of the specified item, remove it
            if (entry.Value.Equals(item.Value))
            {
                _collection.Remove(item.Key);
                return true;
            }

            return false;
        }

        /// <summary>
        /// Copies the key-value pairs to a given array starting from specified index.
        /// </summary>
        public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
        {
            if (array == null)
                throw new ArgumentNullException();

            var enumerator = _collection.GetInOrderEnumerator();

            while (enumerator.MoveNext() && arrayIndex < array.Length)
            {
                array[arrayIndex] = enumerator.Current;
                arrayIndex++;
            }
        }

        /// <summary>
        /// Clears this instance.
        /// </summary>
        public void Clear()
        {
            _collection = new RedBlackTreeMap<TKey, TValue>(allowDuplicates: false);
        }


        #region IEnumerable implementation

        public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator()
        {
            return _collection.GetInOrderEnumerator();
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

        #endregion
    }

}

using System;
using System.Collections.Generic;

using DataStructures.Common;
using DataStructures.Trees;

namespace DataStructures.SortedCollections
{
    /// <summary>
    /// Sorted List (RBTree-based).
    /// </summary>
    public class SortedList<T> : IEnumerable<T>, ICollection<T>, IList<T> where T : IComparable<T>
    {
        /// <summary>
        /// The internal collection is a Red-Black Tree.
        /// </summary>
        private RedBlackTree<T> _collection { get; set; }


        /// <summary>
        /// Constructor.
        /// </summary>
        public SortedList()
        {
            this._collection = new RedBlackTree<T>();
        }

        /// <summary>
        /// Returns true if list is empty; otherwise, false.
        /// </summary>
        public bool IsEmpty
        {
            get { return this.Count == 0; }
        }

        /// <summary>
        /// Gets the count of items in list.
        /// </summary>
        public int Count
        {
            get { return this._collection.Count; }
        }

        public bool IsReadOnly
        {
            get { return false; }
        }

        /// <summary>
        /// Determines whether the current collection contains a specific value.
        /// </summary>
        public bool Contains(T item)
        {
            return _collection.Contains(item);
        }

        /// <summary>
        /// Determines the index of a specific item in the current collection.
        /// </summary>
        public int IndexOf(T item)
        {
            // If the item doesn't exist in collection, return -1
            if (!this.Contains(item))
                return -1;

            int index = 0;
            var enumerator = this._collection.GetInOrderEnumerator();

            while (enumerator.MoveNext())
            {
                // If the current item is found return index
                if (enumerator.Current.IsEqualTo(item))
                    return index;

                // Increment index
                index++;
            }

            return -1;
        }

        /// <summary>
        /// Gets or sets the item at the specified index.
        /// </summary>
        public T this[int index]
        {
            get
            {
                // In case list is empty
                if (IsEmpty)
                    throw new Exception("List is empty.");

                // Validate index range
                if (index < 0 || index >= this.Count)
                    throw new IndexOutOfRangeException();

                var enumerator = this._collection.GetInOrderEnumerator();

                // Keep moving to the next item until index becomes 0
                while (enumerator.MoveNext() && index > 0)
                    index--;

                // Return the enumerator's Current value
                return enumerator.Current;
            }
            set
            {
                try
                {
                    this._collection.Remove(this[index]);
                    this.Add(value);
                }
                catch (IndexOutOfRangeException)
                {
                    // Masks the get method (see above) exception with a new one.
                    throw new IndexOutOfRangeException();
                }
            }
        }

        /// <summary>
        /// Adds the item to list.
        /// </summary>
        public void Add(T item)
        {
            this._collection.Insert(item);
        }

        /// <summary>
        /// Removes the first occurrence of an item from list.
        /// </summary>
        public bool Remove(T item)
        {
            try 
            {
                this._collection.Remove(item);
                return true;
            }
            catch(Exception)
            {
                return false;
            }
        }

        /// <summary>
        /// Inserts the item at the specified index.
        /// </summary>
        public void Insert(int index, T item)
        {
            // It is meaningless to insert at a specific index since after every
            // insert operation, the collection will be rebalanced and the insertion
            // operation itself needs to ensure the sorting criteria, therefore the item
            // item insert at index i might not be the same after the operation has completed.
            throw new NotImplementedException();
        }

        /// <summary>
        /// Removes an item at a specific index.
        /// </summary>
        public void RemoveAt(int index)
        {
            // Validate index range
            if (index < 0 || index >= this.Count)
                throw new IndexOutOfRangeException();

            var enumerator = this._collection.GetInOrderEnumerator();

            // Keep moving to the next item until index becomes 0
            while (enumerator.MoveNext() && index > 0)
                index--;

            // Remove the enumerator's Current value from collection
            this.Remove(enumerator.Current);
        }

        /// <summary>
        /// Copies the items in list to an array starting from a given index.
        /// </summary>
        public void CopyTo(T[] array, int arrayIndex)
        {
            // Validate the array argument
            if(array == null)
                throw new ArgumentNullException("Array cannot be Null.");

            var enumerator = this._collection.GetInOrderEnumerator();

            // Copy the items from the inorder-walker of the tree to the passed array
            while (enumerator.MoveNext() && arrayIndex < array.Length)
            {
                array[arrayIndex] = enumerator.Current;
                arrayIndex++;
            }
        }

        /// <summary>
        /// Clears this instance.
        /// </summary>
        public void Clear()
        {
            this._collection = new RedBlackTree<T>();
        }


        #region IEnumerable implementation

        public IEnumerator<T> GetEnumerator()
        {
            return this._collection.GetInOrderEnumerator();
        }

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return this.GetEnumerator();
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;

namespace DataStructures.Trees
{
    /// <summary>
    /// AVL Tree Data Structure.
    /// </summary>
    public class AVLTree<T> : BinarySearchTree<T> where T : IComparable<T>
    {
        /// <summary>
        /// Override the Root node accessors
        /// </summary>
        public new AVLTreeNode<T> Root
        {
            get { return (AVLTreeNode<T>)base.Root; }
            internal set { base.Root = value; }
        }

        /// <summary>
        /// CONSTRUCTOR.
        /// Allows duplicates by default.
        /// </summary>
        public AVLTree() : base() { }

        /// <summary>
        /// CONSTRUCTOR.
        /// If allowDuplictes is set to false, no duplicate items will be inserted.
        /// </summary>
        public AVLTree(bool allowDuplicates) : base(allowDuplicates) { }


        /// <summary>
        /// Returns the height of a node.
        /// </summary>
        private int _getNodeHeight(AVLTreeNode<T> node)
        {
            if (node == null)
                return -1;
            return node.Height;
        }

        /// <summary>
        /// Updates the height of a node.
        /// </summary>
        private void _updateNodeHeight(AVLTreeNode<T> node)
        {
            if (node == null)
                return;

            // height = 1 + the max between left and right children.
            node.Height = 1 + Math.Max(_getNodeHeight(node.LeftChild), _getNodeHeight(node.RightChild));
        }

        /// <summary>
        /// Updates the height of a node and it's parents' recursivley up to the root of the tree.
        /// </summary>
        private void _updateHeightRecursive(AVLTreeNode<T> node)
        {
            if (node == null)
                return;

            // height = 1 + the max between left and right children.
            node.Height = 1 + Math.Max(_getNodeHeight(node.LeftChild), _getNodeHeight(node.RightChild));

            _updateHeightRecursive(node.Parent);
        }

        /// <summary>
        /// Returns the AVL balance factor for a node.
        /// </summary>
        private int _getBalanceFactor(AVLTreeNode<T> node)
        {
            if (node == null)
                return -1;

            return (_getNodeHeight(node.RightChild) - _getNodeHeight(node.LeftChild));
        }

        /// <summary>
        /// Rotates a node to the left in the AVL tree.
        /// </summary>
        private void _rotateLeftAt(AVLTreeNode<T> currentNode)
        {
            // We check the right child because it's going to be a pivot node for the rotation
            if (currentNode == null || currentNode.HasRightChild == false)
                return;

            // Pivot on *right* child
            AVLTreeNode<T> pivotNode = currentNode.RightChild;

            // Parent of currentNode
            AVLTreeNode<T> parent = currentNode.Parent;

            // Check if currentNode is it's parent's left child.
            bool isLeftChild = currentNode.IsLeftChild;

            // Check if currentNode is the Root
            bool isRootNode = (currentNode == this.Root);

            // Perform the rotation
            currentNode.RightChild = pivotNode.LeftChild;
            pivotNode.LeftChild = currentNode;

            // Update parents references
            currentNode.Parent = pivotNode;
            pivotNode.Parent = parent;

            if (currentNode.HasRightChild)
                currentNode.RightChild.Parent = currentNode;

            //Update the entire tree's Root if necessary
            if (isRootNode)
                this.Root = pivotNode;

            // Update the original parent's child node
            if (isLeftChild)
                parent.LeftChild = pivotNode;
            else if (parent != null)
                parent.RightChild = pivotNode;

            // Update the AVL Heights of each node.
            // _updateHeightRecursive(pivotNode);
            _updateHeightRecursive(currentNode);
        }

        /// <summary>
        /// Rotates a node to the right in the AVL tree.
        /// </summary>
        private void _rotateRightAt(AVLTreeNode<T> currentNode)
        {
            // We check the right child because it's going to be a pivot node for the rotation
            if (currentNode == null || currentNode.HasLeftChild == false)
                return;

            // Pivot on *left* child
            var pivotNode = currentNode.LeftChild;

            // Parent of currentNode
            var parent = currentNode.Parent;

            // Check if currentNode is it's parent's left child.
            bool isLeftChild = currentNode.IsLeftChild;

            // Check if currentNode is the Root
            bool isRootNode = (currentNode == this.Root);

            // Perform the rotation
            currentNode.LeftChild = pivotNode.RightChild;
            pivotNode.RightChild = currentNode;

            // Update parents references
            currentNode.Parent = pivotNode;
            pivotNode.Parent = parent;

            if (currentNode.HasLeftChild)
                currentNode.LeftChild.Parent = currentNode;

            // Update the entire tree's Root if necessary
            if (isRootNode)
                this.Root = pivotNode;

            // Update the original parent's child node
            if (isLeftChild)
                parent.LeftChild = pivotNode;
            else if (parent != null)
                parent.RightChild = pivotNode;

            // Update the AVL Heights of each node.
            // _updateHeightRecursive(pivotNode);
            _updateHeightRecursive(currentNode);
        }

        /// <summary>
        /// Rebalances the tree around a node.
        /// </summary>
        private void _rebalanceSubtreeTreeAt(AVLTreeNode<T> currentNode)
        {
            if (currentNode == null)
                return;

            int balance = _getBalanceFactor(currentNode);

            // Balance the tree only if the balance factor was less than -1 or greater than +1.
            if (Math.Abs(balance) >= 2) // -2 or 2; -3 or 3 ... etc
            {
                // if balance is a positive number: 2, 3 ... etc
                // right subtree outweighs
                if (balance > 0)
                {
                    int rightSubtreeBalance = _getBalanceFactor(currentNode.RightChild);

                    if (rightSubtreeBalance == 0 || rightSubtreeBalance == 1)
                    {
                        // Rotate *LEFT* on current node
                        _rotateLeftAt(currentNode);
                    }
                    else if (rightSubtreeBalance == -1)
                    {
                        // Rotate *RIGHT* on right child
                        _rotateRightAt(currentNode.RightChild);

                        // Rotate *LEFT* on current node
                        _rotateLeftAt(currentNode);
                    }
                }
                // if balance is a negative number: -2, -3 ... etc
                // left subtree outweighs
                else
                {
                    int leftSubtreeBalance = _getBalanceFactor(currentNode.LeftChild);

                    if (leftSubtreeBalance == 0 || leftSubtreeBalance == 1)
                    {
                        // Rotate *RIGHT* on current node
                        _rotateRightAt(currentNode);
                    }
                    else if (leftSubtreeBalance == -1)
                    {
                        // Rotate *LEFT* on left child
                        _rotateLeftAt(currentNode.LeftChild);

                        // Rotate *RIGHT* on right child
                        _rotateRightAt(currentNode);
                    }
                }
            }
        }

        /// <summary>
        /// Rebalances the whole tree around a node.
        /// </summary>
        private void _rebalanceTreeAt(AVLTreeNode<T> node)
        {
            var currentNode = node;
            while (currentNode != null)
            {
                // Update this node's height value.
                _updateNodeHeight(currentNode);

                // Get left and right for comparisons
                var left = currentNode.LeftChild;
                var right = currentNode.RightChild;

                if (_getNodeHeight(left) >= 2 + _getNodeHeight(right))
                {
                    if (currentNode.HasLeftChild && _getNodeHeight(left.LeftChild) >= _getNodeHeight(left.RightChild))
                    {
                        _rotateRightAt(currentNode);
                    }
                    else
                    {
                        _rotateLeftAt(currentNode.LeftChild);
                        _rotateRightAt(currentNode);
                    }
                }
                else if (_getNodeHeight(right) >= 2 + _getNodeHeight(left))
                {
                    if (currentNode.HasRightChild && _getNodeHeight(right.RightChild) >= _getNodeHeight(right.LeftChild))
                    {
                        _rotateLeftAt(currentNode);
                    }
                    else
                    {
                        _rotateRightAt(currentNode.RightChild);
                        _rotateLeftAt(currentNode);
                    }
                }

                currentNode = currentNode.Parent;
            }
        }

        /// <summary>
        /// Inserts an item to the tree.
        /// </summary>
        public override void Insert(T item)
        {
            // New node object
            var newNode = new AVLTreeNode<T>() { Value = item };

            // Invoke the super BST insert node method.
            // This insert node recursively starting from the root and checks for success status (related to allowDuplicates flag).
            // The functions increments count on its own.
            var success = base._insertNode(newNode);

            if (success == false && _allowDuplicates == false)
                throw new InvalidOperationException("Tree does not allow inserting duplicate elements.");

            // Rebalance the tree
            _rebalanceTreeAt(newNode);
        }

        /// <summary>
        /// Inserts an array of elements to the tree.
        /// </summary>
        public override void Insert(T[] collection)
        {
            if (collection == null)
                throw new ArgumentNullException();

            if (collection.Length > 0)
                for (int i = 0; i < collection.Length; ++i)
                    this.Insert(collection[i]);
        }

        /// <summary>
        /// Inserts a list of elements to the tree.
        /// </summary>
        public override void Insert(List<T> collection)
        {
            if (collection == null)
                throw new ArgumentNullException();

            if (collection.Count > 0)
                for (int i = 0; i < collection.Count; ++i)
                    this.Insert(collection[i]);
        }

        /// <summary>
        /// Removes an item fromt he tree
        /// </summary>
        public override void Remove(T item)
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            // Get the node from the tree
            var node = (AVLTreeNode<T>)base._findNode(Root, item);

            // Invoke the BST remove node method.
            bool status = base._remove(node);

            if (status == true)
            {
                // Rebalance the tree
                // node.parent is actually the old parent of the node,
                // which is the first potentially out-of-balance node.
                _rebalanceTreeAt(node);
            }
            else
            {
                throw new Exception("Item was not found.");
            }

            //// Update the node's parent height.
            //_updateHeightRecursively(node.Parent);

            //// Rebalance the tree
            //var parent = node.Parent;
            //while(parent != null)
            //{
            //    _rebalanceSubtreeTreeAt(node.Parent);
            //}
        }

        /// <summary>
        /// Removes the min value from tree.
        /// </summary>
        public override void RemoveMin()
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            // Get the node from the tree
            var node = (AVLTreeNode<T>)base._findMinNode(Root);

            // Invoke the BST remove node method.
            base._remove(node);

            // Rebalance the tree
            // node.parent is actually the old parent of the node,
            // which is the first potentially out-of-balance node.
            _rebalanceTreeAt(node);
        }

        /// <summary>
        /// Removes the max value from tree.
        /// </summary>
        public override void RemoveMax()
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            // Get the node from the tree
            var node = (AVLTreeNode<T>)base._findMaxNode(Root);

            // Invoke the BST remove node method.
            base._remove(node);

            // Rebalance the tree
            // node.parent is actually the old parent of the node,
            // which is the first potentially out-of-balance node.
            _rebalanceTreeAt(node);
        }

    }

}

