    /// <summary>
    /// Binary Search Tree node.
    /// This node extends the vanilla BSTNode class and adds an extra field to it for augmentation.
    /// The BST now augments the subtree-sizes on insert, delete and get-height.
    /// </summary>

    public class BSTRankedNode<T> : BSTNode<T> where T : IComparable<T>
    {
        private int _subtreeSize = 0;

        public BSTRankedNode() : this(default(T), 0, null, null, null) { }
        public BSTRankedNode(T value) : this(value, 0, null, null, null) { }
        public BSTRankedNode(T value, int subtreeSize, BSTRankedNode<T> parent, BSTRankedNode<T> left, BSTRankedNode<T> right)
        {
            base.Value = value;
            SubtreeSize = subtreeSize;
            Parent = parent;
            LeftChild = left;
            RightChild = right;
        }

        // Size of subtrees
        public virtual int SubtreeSize
        {
            get { return this._subtreeSize; }
            set { this._subtreeSize = value; }
        }

        public new BSTRankedNode<T> Parent
        {
            get { return (BSTRankedNode<T>)base.Parent; }
            set { base.Parent = value; }
        }

        public new BSTRankedNode<T> LeftChild
        {
            get { return (BSTRankedNode<T>)base.LeftChild; }
            set { base.LeftChild = value; }
        }

        public new BSTRankedNode<T> RightChild
        {
            get { return (BSTRankedNode<T>)base.RightChild; }
            set { base.RightChild = value; }
        }
    }


    /******************************************************************************/


    /// <summary>
    /// Binary Search Tree Data Structure.
    /// This is teh augmented version of BST. It is augmented to keep track of the nodes subtrees-sizes.
    /// </summary>

    public class AugmentedBinarySearchTree<T> : BinarySearchTree<T> where T : IComparable<T>
    {
        /// <summary>
        /// Override the Root node accessors.
        /// </summary>
        public new BSTRankedNode<T> Root
        {
            get { return (BSTRankedNode<T>)base.Root; }
            set { base.Root = value; }
        }


        /// <summary>
        /// CONSTRUCTOR.
        /// Allows duplicates by default.
        /// </summary>
        public AugmentedBinarySearchTree() : base() { }

        /// <summary>
        /// CONSTRUCTOR.
        /// If allowDuplictes is set to false, no duplicate items will be inserted.
        /// </summary>
        public AugmentedBinarySearchTree(bool allowDuplicates) : base(allowDuplicates) { }


        /// <summary>
        /// Returns the height of the tree.
        /// </summary>
        /// <returns>Hight</returns>
        public override int Height
        {
            get
            {
                if (IsEmpty)
                    return 0;

                var currentNode = this.Root;
                return this._getTreeHeight(currentNode);
            }
        }

        /// <summary>
        /// Returns the Subtrees size for a tree node if node exists; otherwise 0 (left and right nodes of leafs).
        /// This is used in the recursive function UpdateSubtreeSize.
        /// </summary>
        /// <returns>The size.</returns>
        /// <param name="node">BST Node.</param>
        protected int _subtreeSize(BSTRankedNode<T> node)
        {
            if (node == null)
                return 0;
            return node.SubtreeSize;
        }

        /// <summary>
        /// Updates the Subtree Size of a tree node.
        /// Used in recusively calculating the Subtrees Sizes of nodes.
        /// </summary>
        /// <param name="node">BST Node.</param>
        protected void _updateSubtreeSize(BSTRankedNode<T> node)
        {
            if (node == null)
                return;

            node.SubtreeSize = _subtreeSize(node.LeftChild) + _subtreeSize(node.RightChild) + 1;

            _updateSubtreeSize(node.Parent);
        }

        /// <summary>
        /// Remove the specified node.
        /// </summary>
        /// <param name="node">Node.</param>
        /// <returns>>True if removed successfully; false if node wasn't found.</returns>
        protected bool _remove(BSTRankedNode<T> node)
        {
            if (node == null)
                return false;

            var parent = node.Parent;

            if (node.ChildrenCount == 2) // if both children are present
            {
                var successor = _findNextLarger(node);
                node.Value = successor.Value;
                return (true && _remove(successor));
            }

            if (node.HasLeftChild) // if the node has only a LEFT child
            {
                base._replaceNodeInParent(node, node.LeftChild);
                _updateSubtreeSize(parent);
                _count--;

            }
            else if (node.HasRightChild) // if the node has only a RIGHT child
            {
                base._replaceNodeInParent(node, node.RightChild);
                _updateSubtreeSize(parent);
                _count--;
            }
            else //this node has no children
            {
                base._replaceNodeInParent(node, null);
                _updateSubtreeSize(parent);
                _count--;
            }

            return true;
        }

        /// <summary>
        /// Calculates the tree height from a specific node, recursively.
        /// </summary>
        /// <param name="node">Node</param>
        /// <returns>Height of node's longest subtree</returns>
        protected int _getTreeHeight(BSTRankedNode<T> node)
        {
            if (node == null || node.HasChildren == false)
                return 0;

            if (node.ChildrenCount == 2) // it has both a right child and a left child
            {
                if (node.LeftChild.SubtreeSize > node.RightChild.SubtreeSize)
                    return (1 + _getTreeHeight(node.LeftChild));
                return (1 + _getTreeHeight(node.RightChild));
            }

            if (node.HasLeftChild)
            {
                return (1 + _getTreeHeight(node.LeftChild));
            }

            if (node.HasRightChild)
            {
                return (1 + _getTreeHeight(node.RightChild));
            }

            // return-functions-fix
            return 0;
        }

        /// <summary>
        /// Inserts an element to the tree
        /// </summary>
        /// <param name="item">Item to insert</param>
        public override void Insert(T item)
        {
            var newNode = new BSTRankedNode<T>(item);

            // Invoke the super BST insert node method.
            // This insert node recursively starting from the root and checks for success status (related to allowDuplicates flag).
            // The functions increments count on its own.
            var success = base._insertNode(newNode);

            if (success == false && _allowDuplicates == false)
                throw new InvalidOperationException("Tree does not allow inserting duplicate elements.");

            // Update the subtree-size for the newNode's parent.
            _updateSubtreeSize(newNode.Parent);
        }

        /// <summary>
        /// Inserts an array of elements to the tree.
        /// </summary>
        public override void Insert(T[] collection)
        {
            if (collection == null)
                throw new ArgumentNullException();

            if (collection.Length > 0)
                for (int i = 0; i < collection.Length; ++i)
                    this.Insert(collection[i]);
        }

        /// <summary>
        /// Inserts a list of elements to the tree.
        /// </summary>
        public override void Insert(List<T> collection)
        {
            if (collection == null)
                throw new ArgumentNullException();

            if (collection.Count > 0)
                for (int i = 0; i < collection.Count; ++i)
                    this.Insert(collection[i]);
        }

        /// <summary>
        /// Deletes an element from the tree
        /// </summary>
        /// <param name="item">item to remove.</param>
        public override void Remove(T item)
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            var node = (BSTRankedNode<T>)base._findNode(this.Root, item);
            bool status = _remove(node);
            this._updateSubtreeSize(node.Parent);

            // If the element was found, remove it.
            if (status == false)
                throw new Exception("Item was not found.");
        }

        /// <summary>
        /// Removes the min value from tree.
        /// </summary>
        public override void RemoveMin()
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            var node = (BSTRankedNode<T>)_findMinNode(this.Root);
            var parent = node.Parent;
            this._remove(node);

            // Update the subtrees-sizes
            this._updateSubtreeSize(parent);
        }

        /// <summary>
        /// Removes the max value from tree.
        /// </summary>
        public override void RemoveMax()
        {
            if (IsEmpty)
                throw new Exception("Tree is empty.");

            var node = (BSTRankedNode<T>)_findMaxNode(this.Root);
            var parent = node.Parent;
            this._remove(node);

            // Update the subtrees-sizes
            this._updateSubtreeSize(parent);
        }

        /// <summary>
        /// Returns the rank of the specified element
        /// </summary>
        /// <param name="item">Tree element</param>
        /// <returns>Rank(item) if found; otherwise throws an exception.</returns>
        public virtual int Rank(T item)
        {
            var node = (BSTRankedNode<T>)base._findNode(this.Root, item);

            if (node == null)
                throw new Exception("Item was not found.");
            return (this._subtreeSize(node.LeftChild) + 1);
        }

    }

}

using System;
using System.Collections.Generic;

namespace DataStructures.Trees
{
    /// <summary>
    /// B Tree Data Structure. Heavily influenced by Geeks for Geeks article.
    /// https://www.geeksforgeeks.org/b-tree-set-1-introduction-2/
    /// </summary>
    public class BTree<T> where T : IComparable<T>
    {
        private int _count { get; set; }
        private BTreeNode<T> _root { get; set; }
        private int _minDegree;

        /// <summary>
        /// CONSTRUCTOR.
        /// </summary>
        public BTree(int minDegree) {
            this._minDegree = minDegree;
            this._count = 0;
        }

        public BTreeNode<T> Root
        {
            get { return this._root; }
        }

        /// <summary>
        /// Inserts an item to the tree.
        /// </summary>
        public void Insert(T value)
        {
            if (this._root == null)
            {
                this._root = new BTreeNode<T>(this._minDegree);
                this._root.Keys.Add(value);
            }
            else
            {
                if (this._root.Keys.Count >= 2*this._minDegree-1)
                {
                    var newRoot = new BTreeNode<T>(this._minDegree);
                    newRoot.Children.Add(this._root);
                    newRoot.SplitChild(0, this._root);

                    // Which of the 2 children should hold the new value?
                    var i = 0;
                    if (value.CompareTo(newRoot.Keys[0]) > 0)
                    {
                        i++;
                    }
                    newRoot.Children[i].InsertNonFull(value);

                    this._root = newRoot;
                }
                else
                {
                    this._root.InsertNonFull(value);
                }
            }
        }

        /// <summary>
        /// Finds the Node that holds the given value.
        /// </summary>
        public BTreeNode<T> Search(T value)
        {
            if (this._root == null)
                return null;

            return this._root.Search(value);
        }

        /// <summary>
        /// Removes an item from the tree
        /// </summary>
        public void Remove(T item)
        {
            if (this._root == null)
            {
                Console.WriteLine("The B Tree is empty.");
                return;
            }

            this._root.Remove(item);
            if (this._root.Keys.Count == 0)
            {
                if (this._root.IsLeaf)
                {
                    this._root = null;
                }
                else
                {
                  this._root = this.Root.Children[0];
                }
            }
        }
    }

    public class BTreeNode<T> : System.IComparable<BTreeNode<T>> where T : System.IComparable<T>
    {
        private BTreeNode<T> _parent;
        private List<BTreeNode<T>> _children;
        private int _degree;
        private List<T> _keys;

        public BTreeNode(int degree)
        {
            this._degree = degree;
            this._children = new List<BTreeNode<T>>(degree*2-1);
            this._keys = new List<T>(degree*2-1);
        }

        public BTreeNode<T> Parent
        {
            get { return this._parent; }
            set { this._parent = value; }
        }

        public List<T> Keys
        {
            set { this._keys = value; }
            get { return this._keys; }
        }

        public List<BTreeNode<T>> Children
        {
            set { this._children = value; }
            get { return this._children; }
        }

        public bool IsLeaf
        {
            get { return (this._children.Count == 0); }
        }

        /// <summary>
        /// A utility function that returns the index of the first key
        /// that is greater than or equal to k.
        /// </summary>
        public int FindKey(T value)
        {
            return this.Keys.FindLastIndex(searching => value.CompareTo(searching) > 0) + 1;
        }

        public void Remove(T value)
        {
            var index = this.FindKey(value);

            // We found the key!
            if (index < this.Keys.Count && value.CompareTo(this.Keys[index]) == 0)
            {
                if (this.IsLeaf)
                    this.RemoveFromLeaf(index);
                else
                    this.RemoveFromNonLeaf(index);
            }
            else
            {
                if (this.IsLeaf)
                    return;

                var didMergeLast = (index == this.Children.Count);

                if (this.Children[index].Keys.Count < this._degree)
                    this.Fill(index);

                // If the last child has been merged, it must have merged with the previous 
                // child and so we recurse on the (idx-1)th child. Else, we recurse on the 
                // (idx)th child which now has atleast t keys 
                if (didMergeLast && index > this.Children.Count) 
                    this.Children[index-1].Remove(value); 
                else
                    this.Children[index].Remove(value); 
            }
        }

        /// <summary>
        /// Removes the key at index from this leaf node.
        /// </summary>
        public void RemoveFromLeaf(int index)
        {
            this.Keys.RemoveAt(index);
        }

        /// <summary>
        /// Removes the key at index from this non-leaf node.
        /// </summary>
        public void RemoveFromNonLeaf(int index)
        {
            // If the child that precedes our key has atleast this._degree keys, 
            // find the predecessor of our key in the subtree rooted at the child 
            // at index. Replace our key by it's pred. Recursively delete pred in
            // the list of children.
            if (this.Children[index].Keys.Count >= this._degree)
            {
                var pred = this.GetPredecessor(index);
                this.Keys[index] = pred;
                this.Children[index].Remove(pred);
            }
            // If the child has less than this._degree keys, examine the child on 
            // the other side. If it has atleast this._degree keys, find the successor
            // of the key in the subtree rooted at our next child. Replace the key with
            // the successor. Recursively delete the successor in the next child.
            else if (this.Children[index+1].Keys.Count >= this._degree)
            {
                var succ = this.GetSuccessor(index);
                this.Keys[index] = succ;
                this.Children[index+1].Remove(succ);
            }
            // If both the previous child and the next child has less than this._degree 
            // keys, merge our key and all of the next child into the previous child.
            // Now the previous child contains 2 * this._degree - 1 keys. Recursively 
            // delete our key from the previous child. 
            else
            {
                this.Merge(index);
                this.Children[index].Remove(this.Keys[index]);
            }
        }

        /// <summary>
        /// Fills the Child at index, which has fewer than this._degree-1 keys.
        /// </summary>
        private void Fill(int index)
        {
            // If the previous child has keys to spare, take them.
            if (index != 0 && this.Children[index-1].Keys.Count >= this._degree)
                this.BorrowFromPrevious(index);
            // If the next child has keys to spare, take them.
            else if (index != this.Keys.Count && this.Children[index].Keys.Count >= this._degree)
                this.BorrowFromNext(index);
            // Merge this sibling with the next, or previous in the event that this
            // is the last child.
            else
            {
                if (index != this.Children.Count-1)
                    this.Merge(index);
                else
                    this.Merge(index-1);
            }
        }

        /// <summary>
        /// Gets the highest value in the tree rooted at the child at index.
        /// </summary>
        private T GetPredecessor(int index)
        {
            var node = this.Children[index];
            while (!node.IsLeaf)
                node = node.Children[node.Children.Count-1];
            return node.Keys[node.Keys.Count-1];
        }

        /// <summary>
        /// Gets the lowest value in the tree rooted at the child at index+1.
        /// </summary>
        private T GetSuccessor(int index)
        {
            var node = this.Children[index+1];
            while (!node.IsLeaf)
                node = node.Children[0];
            return node.Keys[0];
        }

        /// <summary>
        /// Merges the child at index with the child at index+1.
        /// </summary>
        private void Merge(int index)
        {
            var child = this.Children[index];
            var sibling = this.Children[index+1];

            // Add our key and the siblings keys to the child.
            child.Keys.Insert(this._degree-1, this.Keys[index]);
            this.Keys.RemoveAt(index);
            child.Keys.AddRange(sibling.Keys);

            // Now move the children.
            if (!child.IsLeaf)
                child.Children.AddRange(sibling.Children);

            this.Children.RemoveAt(index+1);
        }

        /// <summary>
        /// Pulls a key from the previous sibling and inserts it in the child
        /// at index.
        /// </summary>
        private void BorrowFromPrevious(int index)
        {
            var child = this.Children[index];
            var sibling = this.Children[index-1];

            // Rotate keys: sibling > parent > child
            child.Keys.Insert(0, this.Keys[index-1]);
            this.Keys[index-1] = sibling.Keys[sibling.Keys.Count-1];
            sibling.Keys.RemoveAt(sibling.Keys.Count-1);

            // Rotate children, if its not a leaf node
            if (!child.IsLeaf)
            {
                child.Children.Insert(0, sibling.Children[sibling.Keys.Count-1]);
                sibling.Children.RemoveAt(sibling.Keys.Count-1);
            }
        }

        /// <summary>
        /// Pulls a key from the next sibling and inserts it in the child
        /// at index.
        /// </summary>
        private void BorrowFromNext(int index)
        {
            var child = this.Children[index];
            var sibling = this.Children[index+1];

            // Rotate keys sibling > parent > child
            child.Keys.Add(this.Keys[index]);
            this.Keys[index] = sibling.Keys[0];
            sibling.Keys.RemoveAt(0);

            // Rotate children if it's not a leaf node
            if (!child.IsLeaf)
            {
                child.Children.Add(sibling.Children[0]);
                sibling.Children.RemoveAt(0);
            }
        }

        /// <summary>
        /// Finds the Node that holds the given value.
        /// </summary>
        public BTreeNode<T> Search(T value)
        {
            var found = this.Keys.FindIndex(searching => value.CompareTo(searching) == 0);
            if (found != -1)
                return this;
            if (found == -1 && this.IsLeaf)
                return null;

            // Find the child 
            found = this.Keys.FindLastIndex(searching => value.CompareTo(searching) > 0) + 1;
            return this.Children[found].Search(value);
        }

        /// <summary>
        /// Assumes value can be inserted. Callers should verify this.Keys has
        /// enough space.
        /// </summary>
        public void InsertNonFull(T value)
        {
            if (this.IsLeaf)
            {
                // Find where the new key should be inserted.
                var i = this.Keys.FindLastIndex(
                    delegate(T compare)
                    {
                        return value.CompareTo(compare) > 0;
                    }
                ) + 1;
                this.Keys.Insert(i, value);
            }
            else
            {
                // Find which child to explore
                var i = this.Keys.FindLastIndex(
                    delegate(T compare)
                    {
                        return value.CompareTo(compare) > 0;
                    }
                ) + 1;

                if (this.Children[i].Keys.Count >= 2*this._degree-1)
                {
                    this.SplitChild(i, this.Children[i]);

                    // One of the new nodes will need to have our value.
                    if (value.CompareTo(this.Keys[i]) > 0)
                        i++;
                }
                this.Children[i].InsertNonFull(value);
            }
        }

        /// <summary>
        /// Splits the given child in 2
        /// </summary>
        public void SplitChild(int i, BTreeNode<T> child)
        {
            // Create a new Node which will store this._degree - 1 keys.
            var node = new BTreeNode<T>(child._degree);

            // Copy the keys over, leaving out the middle key
            var mid = child.Keys[child._degree-1];
            node.Keys = child.Keys.GetRange(child._degree, child._degree-1);
            child.Keys = child.Keys.GetRange(0, child._degree-1);

            // Copy the children over
            if (!child.IsLeaf)
            {
                node.Children = child.Children.GetRange(child._degree, child._degree);
                child.Children = child.Children.GetRange(0, child._degree);
            }

            // Insert the new node in this list of children.
            // Keep in mind the index i is for the keys, not children.
            this.Children.Insert(i+1, node);

            // One of the keys of child will move up to this node.
            this.Keys.Insert(i, mid);
        }

        /// <summary>
        /// Compares to.
        /// </summary>
        public virtual int CompareTo(BTreeNode<T> other)
        {
            if (other == null)
                return -1;

            if (other.Children.Count != this.Children.Count)
                return -1;

            return 0;
        }
    }

}

using System;
using System.Collections.Generic;

using System.Collections;

using DataStructures.Common;

namespace DataStructures.Trees
{
    /// <summary>
    /// Implements a generic Binary Search Tree data structure.
    /// </summary>
    /// <typeparam name="T">Type of elements.</typeparam>
    public class BinarySearchTree<T> : IBinarySearchTree<T> where T : IComparable<T>
    {
        /// <summary>
        /// Specifies the mode of travelling through the tree.
        /// </summary>
        public enum TraversalMode
        {
            InOrder = 0,
            PreOrder = 1,
            PostOrder = 2
        }


        /// <summary>
        /// TREE INSTANCE VARIABLES
        /// </summary>
        /// <returns></returns>
        protected int _count { get; set; }
        protected bool _allowDuplicates { get; set; }
        protected virtual BSTNode<T> _root { get; set; }

        public virtual BSTNode<T> Root
        {
            get { return this._root; }
            internal set { this._root = value; }
        }


        /// <summary>
        /// CONSTRUCTOR.
        /// Allows duplicates by default.
        /// </summary>
        public BinarySearchTree()
        {
            _count = 0;
            _allowDuplicates = true;
            Root = null;
        }

        /// <summary>
        /// CONSTRUCTOR.
        /// If allowDuplictes is set to false, no duplicate items will be inserted.
        /// </summary>
        public BinarySearchTree(bool allowDuplicates)
        {
            _count = 0;
            _allowDuplicates = allowDuplicates;
            Root = null;
        }


        /// <summary>
        /// Replaces the node's value from it's parent node object with the newValue.
        /// Used in the recusive _remove function.
        /// </summary>
        /// <param name="node">BST node.</param>
        /// <param name="newNode">New value.</param>
        protected virtual void _replaceNodeInParent(BSTNode<T> node, BSTNode<T> newNode = null)
        {
            if (node.Parent != null)
            {
                if (node.IsLeftChild)
                    node.Parent.LeftChild = newNode;
                else
                    node.Parent.RightChild = newNode;
            }
            else
            {
                Root = newNode;
            }

            if (newNode != null)
                newNode.Parent = node.Parent;
        }

        /// <summary>
        /// Remove the specified node.
        /// </summary>
        /// <param name="node">Node.</param>
        /// <returns>>True if removed successfully; false if node wasn't found.</returns>
        protected virtual bool _remove(BSTNode<T> node)
        {
            if (node == null)
                return false;

            var parent = node.Parent;

            if (node.ChildrenCount == 2) // if both children are present
            {
                var successor = _findNextLarger(node);
                node.Value = successor.Value;
                return (true && _remove(successor));
            }

            if (node.HasLeftChild) // if the node has only a LEFT child
            {
                _replaceNodeInParent(node, node.LeftChild);
                _count--;

            }
            else if (node.HasRightChild) // if the node has only a RIGHT child
            {
                _replaceNodeInParent(node, node.RightChild);
                _count--;
            }
            else //this node has no children
            {
                _replaceNodeInParent(node, null);
                _count--;
            }

            return true;
        }

        /// <summary>
        /// Inserts a new node to the tree.
        /// </summary>
        /// <param name="currentNode">Current node to insert afters.</param>
        /// <param name="newNode">New node to be inserted.</param>
        protected virtual bool _insertNode(BSTNode<T> newNode)
        {
            // Handle empty trees
            if (this.Root == null)
            {
                Root = newNode;
                _count++;
                return true;
            }

            if (newNode.Parent == null)
                newNode.Parent = this.Root;

            // Check for value equality and whether inserting duplicates is allowed
            if (_allowDuplicates == false && newNode.Parent.Value.IsEqualTo(newNode.Value))
            {
                return false;
            }

            // Go Left
            if (newNode.Parent.Value.IsGreaterThan(newNode.Value)) // newNode < parent
            {
                if (newNode.Parent.HasLeftChild == false)
                {
                    newNode.Parent.LeftChild = newNode;

                    // Increment count.
                    _count++;

                    return true;
                }

                newNode.Parent = newNode.Parent.LeftChild;
                return _insertNode(newNode);
            }
            // Go Right

            if (newNode.Parent.HasRightChild == false)
            {
                newNode.Parent.RightChild = newNode;

                // Increment count.
                _count++;

                return true;
            }

            newNode.Parent = newNode.Parent.RightChild;
            return _insertNode(newNode);
        }

        /// <summary>
        /// Calculates the tree height from a specific node, recursively.
        /// Time-complexity: O(n), where n = number of nodes.
        /// </summary>
        /// <param name="node">Node</param>
        /// <returns>Height of node's longest subtree</returns>
        protected virtual int _getTreeHeight(BSTNode<T> node)
        {
            if (node == null)
                return 0;
            // Is leaf node
            if (node.IsLeafNode)
                return 1;
            // Has two children
            if (node.ChildrenCount == 2)
                return (1 + Math.Max(_getTreeHeight(node.LeftChild), _getTreeHeight(node.RightChild)));
            // Has only left
            if (node.HasLeftChild)
                return (1 + _getTreeHeight(node.LeftChild));
            // Has only right
            return (1 + _getTreeHeight(node.RightChild));
        }

        /// <summary>
        /// Finds a node inside another node's subtrees, given it's value.
        /// </summary>
        /// <param name="currentNode">Node to start search from.</param>
        /// <param name="item">Search value</param>
        /// <returns>Node if found; otherwise null</returns>
        protected virtual BSTNode<T> _findNode(BSTNode<T> currentNode, T item)
        {
            if (currentNode == null)
                return currentNode;

            if (item.IsEqualTo(currentNode.Value))
            {
                return currentNode;
            }

            if (currentNode.HasLeftChild && item.IsLessThan(currentNode.Value))
            {
                return _findNode(currentNode.LeftChild, item);
            }

            if (currentNode.HasRightChild && item.IsGreaterThan(currentNode.Value))
            {
                return _findNode(currentNode.RightChild, item);
            }

            // Return-functions-fix
            return null;
        }

        /// <summary>
        /// Returns the min-node in a subtree.
        /// Used in the recusive _remove function.
        /// </summary>
        /// <returns>The minimum-valued tree node.</returns>
        /// <param name="node">The tree node with subtree(s).</param>
        protected virtual BSTNode<T> _findMinNode(BSTNode<T> node)
        {
            if (node == null)
                return node;

            var currentNode = node;

            while (currentNode.HasLeftChild)
                currentNode = currentNode.LeftChild;

            return currentNode;
        }

        /// <summary>
        /// Returns the max-node in a subtree.
        /// Used in the recusive _remove function.
        /// </summary>
        /// <returns>The maximum-valued tree node.</returns>
        /// <param name="node">The tree node with subtree(s).</param>
        protected virtual BSTNode<T> _findMaxNode(BSTNode<T> node)
        {
            if (node == null)
                return node;

            var currentNode = node;

            while (currentNode.HasRightChild)
                currentNode = currentNode.RightChild;

            return currentNode;
        }

        /// <summary>
        /// Finds the next smaller node in value compared to the specified node.
        /// </summary>
        protected virtual BSTNode<T> _findNextSmaller(BSTNode<T> node)
        {
            if (node == null)
                return node;

            if (node.HasLeftChild)
                return _findMaxNode(node.LeftChild);

            var currentNode = node;
            while (currentNode.Parent != null && currentNode.IsLeftChild)
                currentNode = currentNode.Parent;

            return currentNode.Parent;
        }

        /// <summary>
        /// Finds the next larger node in value compared to the specified node.
        /// </summary>
        protected virtual BSTNode<T> _findNextLarger(BSTNode<T> node)
        {
            if (node == null)
                return node;

            if (node.HasRightChild)
                return _findMinNode(node.RightChild);

            var currentNode = node;
            while (currentNode.Parent != null && currentNode.IsRightChild)
                currentNode = currentNode.Parent;

            return currentNode.Parent;
        }

        /// <summary>
        /// A recursive private method. Used in the public FindAll(predicate) functions.
        /// Implements in-order traversal to find all the matching elements in a subtree.
        /// </summary>
        /// <param name="currentNode">Node to start searching from.</param>
        /// <param name="match"></param>
        protected virtual void _findAll(BSTNode<T> currentNode, Predicate<T> match, ref List<T> list)
        {
            if (currentNode == null)
                return;

            // call the left child
            _findAll(currentNode.LeftChild, match, ref list);

            if (match(currentNode.Value)) // match
            {
                list.Add(currentNode.Value);
            }

            // call the right child
            _findAll(currentNode.RightChild, match, ref list);
        }

        /// <summary>
        /// In-order traversal of the subtrees of a node. Returns every node it vists.
        /// </summary>
        /// <param name="currentNode">Node to traverse the tree from.</param>
        /// <param name="list">List to add elements to.</param>
        protected virtual void _inOrderTraverse(BSTNode<T> currentNode, ref List<T> list)
        {
            if (currentNode == null)
                return;

            // call the left child
            _inOrderTraverse(currentNode.LeftChild, ref list);

            // visit node
            list.Add(currentNode.Value);

            // call the right child
            _inOrderTraverse(currentNode.RightChild, ref list);
        }


